(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c30"]=[{"id":"00004691","register_sub_id":"101","register_pk":"105681","name":"神明社神輿殿","kana":"しんめいしゃみこしでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26485908,"lng":140.11507614,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"05 － 0120","desc":"神明社本殿の左手前に位置し，参道に正面を見せる。桁行１３尺，梁間１０尺半の木造平屋建，切妻造の妻入で，鉄板葺とする。背面に４尺の下屋がつき，片流屋根をかける。正面に上り段を設け，桟唐戸４枚を建込んでいる。外壁は簓子下見板張である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004691"},{"id":"00004693","register_sub_id":"101","register_pk":"105683","name":"神明社両部鳥居","kana":"しんめいしゃりょうぶとりい","category":"宗教","subcategory":"建築物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26504481,"lng":140.11455962,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、高さ4.0m、幅2.7m","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"05 － 0122","desc":"稲荷鳥居から石段を登った位置に建つ木製の鳥居。反りのある笠木と島木，柱上に台輪をもち，両柱の前後に袖柱をもつ両部鳥居の形式である。全高約４ｍ，柱間２．７ｍで，柱高２．４ｍに対して１５ｃｍの内転びを持つ。笠木上に鉄板葺の屋根を載せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004693"},{"id":"00009696","register_sub_id":"101","register_pk":"195525","name":"長谷寺大仏殿","kana":"ちょうこくじだいぶつでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市赤田字上田表115","lat":39.42843167,"lng":140.10292335,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"05 － 0194","desc":"高さ約八メートルの十一面観音立像を安置する。宝形造銅板葺で周囲に裳階を廻らし、正面に向拝を付ける。上層の軒を扇垂木として正面に観相窓を穿ち、下層は向拝周りを中心として雲龍や花鳥などの立体的な彫刻で飾る。当地では赤田の大仏として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009696"},{"id":"00012468","register_sub_id":"101","register_pk":"367763","name":"東北聖書バプテスト十文字教会","kana":"とうほくせいしょばぷてすとじゅうもんじきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"秋田県","address":"秋田県横手市十文字町字栄町18-1、19-1","lat":39.223415,"lng":140.522049,"geo_status":"geocoded","era":"昭和24年／昭和51年頃改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"05 － 0220","desc":"東と南を街路に面する角地に東面して建つプロテスタント教会堂。木造平屋建、切妻造妻入の大屋根をかけ、正面大棟上に鐘塔を載せ、正面をモルタル大壁で整える。内部に無柱の均質な礼拝空間をつくる。市街中心部のランドマークとして地域に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012468"},{"id":"00010725","register_sub_id":"101","register_pk":"201560","name":"松ヶ崎八幡神社拝殿・幣殿及び本殿覆屋","kana":"まつがさきはちまんじんじゃはいでん・へいでんおよびほんでんおおいや","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県由利本荘市松ヶ崎字宮ノ腰102","lat":39.500441,"lng":140.049843,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"05 ‐ 0208","desc":"切妻造の本殿覆屋と拝殿を幣殿で繋ぎ、権現造風の外観をなす。拝殿は正面に間口の広い一間向拝を付け、内部は格天井の格間に花鳥などの彩画を施す。幣殿内には黒漆塗の四本の円柱で囲む上段の舞殿を設け、格天井に龍を描く。舞殿を内設した独特な形式の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010725"},{"id":"00010724","register_sub_id":"101","register_pk":"201559","name":"松ヶ崎八幡神社本殿","kana":"まつがさきはちまんじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県由利本荘市松ヶ崎字宮ノ腰102","lat":39.500566,"lng":140.049821,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"05 ‐ 0207","desc":"覆屋内に建つ三間社流造本殿。軒唐破風付、板葺で三方に縁を廻らし、身舎柱上の出組で妻飾を迫出す。軸部を透漆塗として木理を引立て、虹梁の渦紋に草花を織交ぜる。蟇股や頭貫地紋彫などに花鳥や龍の彫刻類を配して極彩色で荘厳するなど、華やかな意匠の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010724"},{"id":"00008616","register_sub_id":"101","register_pk":"149337","name":"森子大物忌神社拝殿及び幣殿","kana":"もりこおおものいみじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県由利本荘市森子字八乙女下99-1","lat":39.30594292,"lng":140.09532601,"geo_status":"db","era":"安政2年(1855)／大正4年増築・昭和25年・昭和48年改修","year":1855,"year_source":"converted","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"05 － 0189","desc":"本殿の前方に位置する。桁行3間梁間3間で、背面を2間増築する。入母屋造銅板葺、正面に千鳥破風と軒唐破風付1間向拝を付け、背面に切妻屋根を突出する。円柱で、木鼻付出三斗を組み、中備に蟇股を配する。繋虹梁上に飾られる一対の力士像が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008616"},{"id":"00008615","register_sub_id":"101","register_pk":"149336","name":"森子大物忌神社本殿","kana":"もりこおおものいみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県由利本荘市森子字八乙女下99-1","lat":39.30596255,"lng":140.09516072,"geo_status":"db","era":"大正4年／昭和25年改修","year":1915,"year_source":"converted","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積19㎡、渡廊付","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"05 － 0188","desc":"八乙女山の中腹に東面して建つ。3間社流造、銅板葺。周囲に高欄付切目縁をまわす。円柱で三斗組とし、妻は二重虹梁大瓶束。正面中央間に両開桟唐戸を装置し、その前方のみ木階を設け、庇の虹梁を高く架け、雲龍の彫刻を飾る。効果的に彫刻装飾が配されている","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008615"},{"id":"00000944","register_sub_id":"101","register_pk":"101934","name":"旧南照寺千手観音堂","kana":"きゅうなんしょうじせんじゅかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町川島字川島平1918","lat":37.16039207,"lng":139.73921165,"geo_status":"db","era":"寛政9","year":1797,"year_source":"db","year_min":1797,"year_max":1797,"year_label":null,"structure":"木造平屋建，鉄板葺，建築面積25㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"07 － 0029","desc":"小規模な妻入の仏堂。もと茅葺で，正面１間分は間口いっぱい向拝部分とし，虹梁や組物等で飾る。正面の屋根のみ唐破風造とする独特の構えになる。屋敷地の奥手にあるが，旧街道から直接見通せる位置に建っており，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000944"},{"id":"00002112","register_sub_id":"101","register_pk":"103102","name":"興國山徳昌寺庫裡","kana":"こうこくざんとくしょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町田島字寺前甲2970","lat":37.19595874,"lng":139.77897302,"geo_status":"db","era":"文政3","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積297㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"07 － 0050","desc":"本堂北西に建ち，部材の墨書から文政３年の建立とわかる。南北棟で，南面が入母屋造，北面が切妻造になる。平面は６間取形式で，南側に床・棚付の座敷を配し，北側を土間とする。入口側の北妻面を大きくみせ，高い庇を廻すなど，一般民家と異なる外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002112"},{"id":"00002113","register_sub_id":"101","register_pk":"103103","name":"興國山徳昌寺金毘羅堂","kana":"こうこくざんとくしょうじこんぴらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町田島字寺前甲2970","lat":37.19612373,"lng":139.77920627,"geo_status":"db","era":"安永5","year":1776,"year_source":"db","year_min":1776,"year_max":1776,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"07 － 0051","desc":"本堂の北東に建つ。堂内にある遷宮銘札より安永５年の建立で，大工は地元田島東町の佐藤忠治とわかる。桁行・梁間とも１０尺強の小規模な３間堂であるが，出桁造として深い軒をつくる。側廻りを角柱，組物を三斗と簡素であるが，つくりは正統的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002113"},{"id":"00002111","register_sub_id":"101","register_pk":"103101","name":"興國山徳昌寺本堂","kana":"こうこくざんとくしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町田島字寺前甲2970","lat":37.19591444,"lng":139.77918819,"geo_status":"db","era":"天保15","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積327㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"07 － 0049","desc":"田島町の中心街の南，山裾に位置する曹洞宗寺院。本堂は北面して建ち，大工は越後蒲原郡の源蔵であった。平面は基本的に６室構成で，庫裡に接する北西隅に廊下座敷を設ける。全体的にたちの高い比例で，側廻りの柱も長く，江戸末期の造形をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002111"},{"id":"00002507","register_sub_id":"101","register_pk":"103497","name":"善導寺庫裡","kana":"ぜんどうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県郡山市清水台1-1-23","lat":37.397171,"lng":140.381897,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積282㎡","structure_material":"木造平屋一部2階建","registered":"2001.11.20(平成13.11.20)","register_no":"07 － 0062","desc":"本堂北側に廊下で連結して建ち，入母屋造の東妻面を正面とする。東西に細長い建物で，鉄板葺の屋根の南面には明かり窓を設ける。６畳間３室と１０畳間４室を並列させ土間廻りを巧みに合わせた平面で，一部を２階建とするなど，近代の造形が発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002507"},{"id":"00010557","register_sub_id":"101","register_pk":"201131","name":"善導寺鐘楼","kana":"ぜんどうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"福島県","address":"福島県郡山市清水台1-163-1","lat":37.39709,"lng":140.382176,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造、瓦葺、面積14㎡","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"07－0161","desc":"浄土宗寺院境内の東方に建つ。桁行三間梁間一間、切妻造本瓦葺で、高欄付の縁を廻らせて二階建風とし、法隆寺鐘楼に類似した形態をもつ。文化財保護委員会技官佐藤登の設計になり、人字割束やエンタシス付の太い円柱などに、古代建築意匠の習熟が窺える鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010557"},{"id":"00002506","register_sub_id":"101","register_pk":"103496","name":"善導寺本堂","kana":"ぜんどうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県郡山市清水台1-1-23","lat":37.396957,"lng":140.381775,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積322㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"07 － 0061","desc":"入母屋造・桟瓦葺，正面向拝付の本堂建築。棟札より明治４２年の上棟で，棟梁は帝室技芸員の第９代伊藤平左衛門とわかる。舞良戸を多用した簡素な住宅風の外観構成に比べ，彫刻や欄間で飾って彩色を施した内陣廻りは，当時の造形感覚を顕著に示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002506"},{"id":"00012482","register_sub_id":"101","register_pk":"367777","name":"日本聖公会郡山聖ペテロ聖パウロ教会聖堂","kana":"にっぽんせいこうかいこおりやませいぺてろせいぱうろきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県郡山市麓山二丁目235","lat":37.39521,"lng":140.36998,"geo_status":"geocoded","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、建築面積210㎡、塔屋付","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0197","desc":"市中心部の高台に建つ。鉄筋コンクリート造、東西棟の切妻造で、北面東端に切妻造の玄関、西端に塔屋を突出する。塔屋隅部やバットレスに柱形を表す外観、シザーズトラスとアーチ梁を併用した小屋組など優れたゴシック意匠をみせる教会建築。設計は上林敬吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012482"},{"id":"00001655","register_sub_id":"101","register_pk":"102645","name":"日本基督教団若松栄町教会","kana":"にほんきりすときょうだんわかまつさかえまちきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市西栄町8-36","lat":37.494644,"lng":139.92601,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積208㎡、塔屋付","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"07 － 0039","desc":"木造下見板張りのゴシック式教会堂で、会堂部の外郭はラテン十字を描く。ヴォーリズ設計の福島教会を手本としたと伝えられ、４５度振った玄関部に尖塔付きの角塔をたちあげる。礼拝堂内のタイバーを用いた架構も時代性をよく示しており貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001655"},{"id":"00014732","register_sub_id":"101","register_pk":"518990","name":"無能寺山門","kana":"むのうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県伊達郡桑折町字上町4-2","lat":37.85014444,"lng":140.51776389,"geo_status":"db","era":"元治元年(1864)","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造、瓦葺、間口3.6m、袖塀付","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"07 - 0283","desc":"桑折宿に位置する浄土宗寺院の薬医門。参道を西進した境内入口に東面して建つ切妻造桟瓦葺で木太い本柱、控柱の頂部を各々冠木で固める。梁を四筋架け、梁先の大斗実肘木で桁を受け、冠木と桁の間に支輪を設ける。ケヤキの良材を使い、雄大な構えの山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014732"},{"id":"00000559","register_sub_id":"101","register_pk":"101549","name":"上杉神社稽照殿","kana":"うえすぎじんじゃけいしょうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市丸の内1-4-13","lat":37.90963534,"lng":140.1044605,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造２階建，銅板葺，建築面積149㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"06 － 0027","desc":"上杉神社再興時に建築された宝物殿で，設計は伊東忠太の手になると伝える。鉄筋コンクリート造で和風の外観を比較的忠実に再現しており，全体を２層の銅板葺きとし，２階には高欄を廻す。数多くの上杉家由来の品を納める宝物殿として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000559"},{"id":"00009886","register_sub_id":"101","register_pk":"196033","name":"熊野神社拝殿","kana":"くまのじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県村山市大字湯野沢字院内2680-1","lat":38.47930197,"lng":140.29450609,"geo_status":"db","era":"江戸中期／江戸後期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、鉄板葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"06 － 0147","desc":"本殿前面に建つ方三間の拝殿で、入母屋造鉄板葺、正面一間向拝付とし、四周に切目縁を廻らせる。中央間後寄りの方一間を上段の内陣とし、外陣は虹梁で柱を省く。木鼻形状などの細部意匠に地方的特色を示すとともに、当地方における熊野信仰の様態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009886"},{"id":"00009885","register_sub_id":"101","register_pk":"196032","name":"熊野神社本殿","kana":"くまのじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県村山市大字湯野沢字院内2680-1","lat":38.47934141,"lng":140.29437297,"geo_status":"db","era":"明治14","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"06 － 0146","desc":"山中の境内最奥部に東面して建つ。一間社流造、鉄板葺で、四周に縁高欄を廻らし、正面に浜床と階を設ける。身舎柱に出組をのせ、妻飾は二重虹梁とする。海老虹梁持送や庇の手挟、蟇股、桁隠など各部材を、四神や花鳥を主題とした精緻な彫刻で華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009885"},{"id":"00002503","register_sub_id":"101","register_pk":"103493","name":"清風荘（旧宝幢寺書院）","kana":"せいふうそう（きゅうほうどうじしょいん）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県山形市東原町2-16-7","lat":38.24563055,"lng":140.34457155,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積290㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"06 － 0039","desc":"当地にあった真言宗の巨刹宝幢寺の書院で，北側の池泉回遊式庭園を臨むように建つ。片入母屋の屋根を架けた簡素な外観であるが，内部は高い格式を示す上段の間に端正な床・棚・付書院を設け，用材も吟味されており，上質な書院造の遺構になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002503"},{"id":"00010731","register_sub_id":"101","register_pk":"201566","name":"善寳寺五重塔","kana":"ぜんぽうじごじゅうのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772216,"lng":139.767939,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造五重塔、銅板葺、建築面積30㎡","structure_material":"木造五重塔","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0166","desc":"参道の南、五百羅漢堂に相対して建つ。三間五重塔婆、瓦棒銅板葺で、組物は尾垂木付三手先とする。和様を基調としつつ、五重軒のみ扇垂木とする。初重中備に十二神将などの透彫、各重の高欄腰組に蟇股を飾る。均整のとれた塔姿に装飾性を備えた、近代の五重塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010731"},{"id":"00010729","register_sub_id":"101","register_pk":"201564","name":"善寳寺五百羅漢堂","kana":"ぜんぽうじごひゃくらかんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772729,"lng":139.768125,"geo_status":"db","era":"安政2","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積167㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0164","desc":"総門と山門を結ぶ参道に南面して建つ。桁行五間梁間四間、軒は二手先で中備に彫刻や蟇股を付す。内部は奥の仏壇前を通路として左右に雛段状の仏壇を置き、側面から背面の壁際にも仏壇を設けて多数の羅漢像を祀り、参詣者の便を図る。羅漢信仰の様相を示す堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010729"},{"id":"00010732","register_sub_id":"101","register_pk":"201567","name":"善寳寺山門","kana":"ぜんぽうじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772544,"lng":139.767939,"geo_status":"db","era":"慶応3","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造2階建、銅板葺、建築面積38㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0167","desc":"参道奥に建つ三間一戸二階二重門。入母屋造瓦棒銅板葺で、正背面に軒唐破風と千鳥破風を付す。組物は三手先で、初重は詰組で軒を平行垂木、二重は中備を蟇股として軒を扇垂木とする。虹梁や小壁に施した波紋などの浮彫、獅子鼻など随所を華やかな彫刻で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010732"},{"id":"00010733","register_sub_id":"101","register_pk":"201568","name":"善寳寺総門","kana":"ぜんぽうじそうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772468,"lng":139.768205,"geo_status":"db","era":"安政3","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造、瓦葺、間口3.3m、左右袖塀付","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0168","desc":"山門前面の参道に建つ、間口三・三メートルの四脚門。切妻造桟瓦葺で左右の袖塀に潜戸を付し、組物を出組として、桁や妻虹梁を持出す。木鼻や虹梁絵様をはじめ、蟇股や琵琶板なども波や動植物を主題とした立体的な彫刻で装飾し、彫刻大工の高い技術力を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010733"},{"id":"00010728","register_sub_id":"101","register_pk":"201563","name":"善寳寺龍王殿","kana":"ぜんぽうじりゅうおうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772884,"lng":139.766797,"geo_status":"db","era":"天保4／昭和後期改修","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0163","desc":"伽藍最奥の本堂背面の小高い地に建つ。龍王殿と開山堂を並べ、間に有栖川宮家の霊牌所をつくる独特な平面を持つ。屋根は入母屋造茅葺形銅板葺で、正面に軒唐破風付の向拝と千鳥破風を二連付し、内外とも彫刻や彩画で飾るなど特異な構成と華やかな意匠を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010728"},{"id":"00010730","register_sub_id":"101","register_pk":"201565","name":"善寳寺龍華庵","kana":"ぜんぽうじりゅうげあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772525,"lng":139.768715,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0165","desc":"参道入口北側に南面して建つ。桁行五間梁間四間で正面に向拝を付す。内部は正面一間通りと中央列の三室、奥一間通りに虹梁で分割し、背面に仏壇を張出す。仏壇前の板敷の他は畳敷とする。彫物は控え目だが、中央間鏡天井の雲龍画など要所に華やかさを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010730"},{"id":"00009125","register_sub_id":"101","register_pk":"164678","name":"鳥海山大物忌神社吹浦口ノ宮後神門及び玉垣","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやうしろしんもんおよびたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07526766,"lng":139.8788995,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"後神門 木造、銅板葺、間口2.4m 玉垣 木造、銅板葺、総延長51m","structure_material":"後神門 木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本殿と摂社月山神社本殿の側面と背面を総延長51メートルの玉垣が囲繞し、背面中央に後神門を構え、神域を区画する。門は一間腕木門で、切妻造銅板葺。角柱を貫で固め、舟肘木で受けた腕木で桁を持出し、一軒疎垂木を配る。両開戸を吊り、貫上に横連子を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009125"},{"id":"00009127","register_sub_id":"101","register_pk":"164680","name":"鳥海山大物忌神社吹浦口ノ宮下拝殿","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやしたはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07434324,"lng":139.87884715,"geo_status":"db","era":"明治12年","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"境内の最下段に位置し、桁行7間梁間5間、入母屋造銅板葺で、正面に3間向拝を付け、軒をせがいで持出す。内部は中央後方の桁行3間梁間2間を上段として格天井を張り、背面の突出部に宮殿を祀る。特徴的な内部空間をもつ広壮な拝殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009127"},{"id":"00009123","register_sub_id":"101","register_pk":"164676","name":"鳥海山大物忌神社吹浦口ノ宮摂社月山神社本殿","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやせっしゃつきやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07521293,"lng":139.87884001,"geo_status":"db","era":"宝永8年(1711)頃／昭和38年改修","year":1711,"year_source":"db","year_min":1711,"year_max":1711,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本殿西に並び建ち、一間社流造銅板葺。身舎は円柱、組物連三斗、中備蟇股、二軒繁垂木。本殿と同規模同形式の社殿であるが、脇障子や蟇股、正面の琵琶板、懸魚などの彫刻が異なる。妻飾に加え、繰りの小さい肘木や虹梁絵様など、細部にも独自性が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009123"},{"id":"00009124","register_sub_id":"101","register_pk":"164677","name":"鳥海山大物忌神社吹浦口ノ宮中門及び廻廊","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやちゅうもんおよびかいろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07515701,"lng":139.8788995,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本殿と摂社月山神社本殿の前方に位置する。登廊上端に接して妻入の中門を開き、その東西に桁行5間の廻廊が延び、両端間を神饌所として間仕切る。いずれも切妻造銅板葺、角柱で舟肘木を載せ、一軒疎垂木、妻豕扠首。端正な外観を構成し、静謐な空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009124"},{"id":"00009126","register_sub_id":"101","register_pk":"164679","name":"鳥海山大物忌神社吹浦口ノ宮拝殿及び登廊","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやはいでんおよびのぼりろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07503804,"lng":139.87889712,"geo_status":"db","era":"昭和18年／平成2年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本殿と月山神社本殿の中央前方、1段低い位置に建つ。桁行5間梁間3間、入母屋造銅板葺で、正面に1間向拝、背面には方1間の突出を設け、中門への登廊を付ける。円柱で組物は大斗肘木。正面中央3間に板唐戸を吊り、両脇間を連子窓とする。厳粛な佇まいの拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009126"},{"id":"00009122","register_sub_id":"101","register_pk":"164675","name":"鳥海山大物忌神社吹浦口ノ宮本殿","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07521412,"lng":139.8789685,"geo_status":"db","era":"宝永8年(1711)頃／昭和38年改修","year":1711,"year_source":"db","year_min":1711,"year_max":1711,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"鳥海山の西方、小高い山の南斜面に占める境内の北奥に南面して建つ中規模の本殿で、一間社流造銅板葺である。身舎は円柱上に連三斗を組み、中備に蟇股を飾る。妻飾は、虹梁上に巻斗と通肘木を2段積上げ、その上に笈形付大瓶束を立てる、特異な形式をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009122"},{"id":"00006704","register_sub_id":"101","register_pk":"107687","name":"鳥海山大物忌神社蕨岡口ノ宮神楽殿","kana":"ちょうかいさんおおものいみじんじゃわらびおかのみやかぐらでん","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡51","lat":38.99643642,"lng":139.94395342,"geo_status":"db","era":"江戸後期／明治初期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"06 － 0090","desc":"西面する境内地の入口から、やや奥の南側に建つ。鐘楼として建立され、神仏分離の際に神楽殿に改められた。南北棟の入母屋造鉄板葺、内転びのある粽付円柱で、吹寄支輪付の出組とし、軒は一軒繁垂木。高欄付の板床で、格天井を張る。歴史的な変遷を物語る遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006704"},{"id":"00006444","register_sub_id":"101","register_pk":"107427","name":"鳥海山大物忌神社蕨岡口ノ宮随神門","kana":"ちょうかいさんおおものいみじんじゃわらびおかのみやずいしんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡51","lat":38.99642528,"lng":139.94359174,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"06 － 0089","desc":"西面する３間１戸八脚門で、切妻造鉄板葺とする。両脇前寄り１間に床を張り、金剛柵をたてる。円柱で、柱上出組とし、中備に蟇股を入れる。軒は二軒繁垂木。妻は二重虹梁大瓶束とし、前方へ持ち出す。伝統的な手法で手固くまとめられた端正な八脚門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006444"},{"id":"00006443","register_sub_id":"101","register_pk":"107426","name":"鳥海山大物忌神社蕨岡口ノ宮本殿","kana":"ちょうかいさんおおものいみじんじゃわらびおかのみやほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡51","lat":38.996952,"lng":139.943863,"geo_status":"db","era":"明治29／昭和28移築","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積263㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"06 － 0088","desc":"桁行３間、梁間６間で、切妻造銅板葺とし、１間向拝を付ける。正面が実長で１３．８ｍに及ぶ大型の社殿で、内部は外陣と内陣に分かれ、さらに内々陣を造る。絵様や装飾的要素は少ないが、木割が大きく、直線的意匠でまとめた、壮大な社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006443"},{"id":"00002738","register_sub_id":"101","register_pk":"103728","name":"明善寺本堂","kana":"みょうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県山形市七日町5-9-3","lat":38.249786,"lng":140.341492,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積327㎡、正面左右塔屋付","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"06 － 0046","desc":"伊東忠太の設計による。内部は前半部を６０畳敷の大広間とし，後半部は中央に内陣を設け，両脇を餘間とし，左奥に書院間を張り出している。正面両脇に鐘楼・鼓楼を設け，向拝と入母屋の妻面を重ねて見せる立面に，伊東の作風が良く表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002738"},{"id":"00002739","register_sub_id":"101","register_pk":"103729","name":"山形聖ペテロ教会礼拝堂","kana":"やまがたせいぺてろきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県山形市木の実町9-22","lat":38.25287845,"lng":140.33422497,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積187㎡、塔屋付","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"06 － 0047","desc":"山形市街の中心部に位置する木造の教会堂。屋根勾配が急な切妻造で，北妻西側に塔屋を設けている。外壁は下見板張で，窓のほとんどを尖塔アーチ型とするのが特徴。小規模ではあるが，外壁立面，内部のトラス架構など意匠を凝らした建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002739"},{"id":"00010735","register_sub_id":"101","register_pk":"201570","name":"龍頭寺開山堂","kana":"りゅうとうじかいさんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡45","lat":38.996242,"lng":139.944123,"geo_status":"db","era":"昭和8／昭和30頃移築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0170","desc":"本堂の背面北寄りに建つ。切妻造平屋建で内部は一室とし、正面と南側面に位牌棚を設ける。外観は妻壁の梁と束組を見せ、壁は下見板張と簡素だが、内部は漆塗を多用し、奥の位牌壇上部欄間には天女や菊、牡丹などの鏝絵を施すなど、凝った意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010735"},{"id":"00010736","register_sub_id":"101","register_pk":"201571","name":"龍頭寺観音堂","kana":"りゅうとうじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡45","lat":38.996174,"lng":139.943998,"geo_status":"db","era":"明治8頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積45㎡","structure_material":"土蔵造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0171","desc":"本堂の正面北寄りに建つ。土蔵造、切妻造妻入、桟瓦葺で正面に向拝を付し、東に物置を附属する。腰は海鼠壁とする。内部は正面一間を土間とする他は板間で、奥に仏壇を置き、中央に大柄な観音像を祀る。向拝虹梁廻りの龍を巻付けた彫刻は立体的で秀逸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010736"},{"id":"00010734","register_sub_id":"101","register_pk":"201569","name":"龍頭寺本堂","kana":"りゅうとうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡45","lat":38.996135,"lng":139.944135,"geo_status":"db","era":"天保15","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"木造平屋一部2階建、銅板葺、建築面積316㎡","structure_material":"木造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0169","desc":"敷地中央に西面する。桁行一三間半梁間六間半、入母屋造銅板葺で正面に唐破風玄関を付す。北半を六間取方丈形式の本堂として内陣北に上段の間を設け、南寄りは土間を持つ庫裏とする。柱が太く内外陣廻りや縁上部の虹梁が目を引く、鳥海修験の遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010734"},{"id":"00009897","register_sub_id":"101","register_pk":"196044","name":"足尾キリスト教会","kana":"あしおきりすときょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市足尾町赤沢2525","lat":36.63940162,"lng":139.44381014,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"09 － 0214","desc":"足尾銅山の玄関口であった通洞地区の東側、赤沢地区に位置する。南正面の中ほどに玄関を設け、西側を一室の会堂とし、東側を牧師の居住空間とする。足尾で初めての本格的な教会堂であるとともに唯一の現存例であり、当時の銅山従事者の信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009897"},{"id":"00004123","register_sub_id":"101","register_pk":"105113","name":"織姫神社神楽殿","kana":"おりひめじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町3889","lat":36.33909217,"lng":139.44463459,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0110","desc":"社殿地に上がる大階段前の西方に位置する。桁行６．２ｍ梁間３．８ｍ，東西棟，入母屋造，銅板葺の木造平屋建で，低い亀腹上に建つ。軒は一軒疎垂木とし，舟肘木で桁を受け，刎高欄を廻す。小林福太郎設計で，社務所とともに社殿地の下の平地の主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004123"},{"id":"00004122","register_sub_id":"101","register_pk":"105112","name":"織姫神社社殿","kana":"おりひめじんじゃしゃでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町3889","lat":36.33922834,"lng":139.44493583,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積140㎡、本殿透塀折曲り延長29メートル付","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0109","desc":"両崖山南斜面の中腹に石積基壇を築き社殿地とする。正面中央に入母屋造，千鳥破風付きの拝殿を置き，その両側に神輿舎と神饌所，背後に両下造の幣殿，向拝と切妻造の本殿を配する。垂木より上を木造とした鉄筋コンクリート造神社建築で，小林福太郎の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004122"},{"id":"00004124","register_sub_id":"101","register_pk":"105114","name":"織姫神社社務所","kana":"おりひめじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町3889","lat":36.33893355,"lng":139.44457048,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建一部地階付、銅板葺、建築面積102㎡","structure_material":"木造平屋建一部地階付","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0111","desc":"神楽殿の南に建ち，渡廊で繋がる。桁行６間半規模の入母屋造，銅板葺で，東面中央に唐破風車寄を突出して式台玄関を設け，南面西側に床棚付き８畳座敷を配する。崖際のため一部鉄筋コンクリート造地階付きで南面及び西面を２階建に見せる。設計は小林福太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004124"},{"id":"00004125","register_sub_id":"101","register_pk":"105115","name":"織姫神社手水舎","kana":"おりひめじんじゃちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町3889","lat":36.33876652,"lng":139.44461886,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積1.4㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0112","desc":"表参道石段の中途，神楽殿・社務所より一段低い平地に建つ。桁行１．９７ｍ梁間０．７ｍ規模，南北棟，切妻造，銅板葺で，社殿と同様，鉄筋コンクリート造で垂木以上を木造とする。神楽殿や社務所とともに，小林福太郎の設計による境内計画の構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004125"},{"id":"00000945","register_sub_id":"101","register_pk":"101935","name":"カトリック松が峰教会","kana":"かとりっくまつがみねきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県宇都宮市松が峰1-1-5","lat":36.5581424,"lng":139.88138783,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造４階建塔屋付，銅板葺，建築面積404㎡","structure_material":"鉄筋コンクリート造４階建塔屋付","registered":"1998.12.11(平成10.12.11)","register_no":"09 － 0013","desc":"大谷石を貼った鉄筋コンクリート造教会堂。階上を聖堂に充てる。両サイドから聖堂にアプローチする正面階段と，八角トンガリ屋根を頂く双塔が荘重な外観を造る。ランドマークとしてもよく知られる。設計は，横浜在住のスイス人建築家マックス・ヒンデル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000945"},{"id":"00014564","register_sub_id":"101","register_pk":"515106","name":"唐澤山神社神楽殿","kana":"からさわやまじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県佐野市栃本町字唐沢山3598-2","lat":36.35378333,"lng":139.599975,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造、銅板葺、建築面積21㎡","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0269","desc":"史跡唐沢山城跡二の丸に位置する神楽殿。入母屋造妻入銅板葺、二軒繁垂木、組物舟肘木。繰形付持送で三方切目縁脇障子付とし、擬宝珠高欄を巡らす。内部は三方蔀戸、格天井で奥に神棚付の舞台と、後座に分かれる。祭礼空間として境内の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014564"},{"id":"00014563","register_sub_id":"101","register_pk":"515105","name":"唐澤山神社参拝門","kana":"からさわやまじんじゃさんぱいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市富士町字富士山1409-3他","lat":36.35359444,"lng":139.60074444,"geo_status":"db","era":"明治16年／明治41年頃移築","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造、銅板葺、間口2.4m","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0268","desc":"神社創建に際して唐沢山山頂に御霊代上屋と共に建てた社殿。切妻造平入銅板葺、二軒繁垂木、正面吹放ち、側面及び背面両脇間を板壁として、背面中央に板扉を吊る。床は四半石敷。当初は門と拝殿を兼ねた役割で、柱は節が多く、創建時の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014563"},{"id":"00014565","register_sub_id":"101","register_pk":"515107","name":"唐澤山神社神橋","kana":"からさわやまじんじゃしんきょう","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県佐野市富士町字富士山1409-3","lat":36.35363889,"lng":139.59909167,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート橋、延長5.0m、幅員3.7m","structure_material":"鉄筋コンクリート橋","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0270","desc":"史跡唐沢山城跡三の丸西方にある四ツ目堀に架かる鉄筋コンクリート造単桁橋。橋長４・６メートル。堀法面に切石積橋台を築き、緩いアーチ形の橋桁を架けて床版を載せる。擬宝珠欄干は御影石で作り、伝統的な石橋風意匠とする近代構法の橋で歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014565"},{"id":"00014562","register_sub_id":"101","register_pk":"515104","name":"唐澤山神社中門祝詞屋及び透塀","kana":"からさわやまじんじゃちゅうもんのりとやおよびすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市富士町字富士山1409-3他","lat":36.35383889,"lng":139.60077778,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"中門祝詞屋 木造、銅板葺、間口2.8m 透塀 木造、銅板葺、総延長52m","structure_material":"中門祝詞屋 木造","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0267","desc":"明治期別格官幣社の本殿を囲む透塀と正面に位置する中門祝詞屋で制限図式の配置。中門祝詞屋は起り付の切妻造妻入銅板葺。透塀は銅板葺で東西に石段と扉を設ける。彫刻は中備蟇股に留めるが、門扉と透塀は菱格子で透かし、腰板にも襷桟を付して優雅な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014562"},{"id":"00014561","register_sub_id":"101","register_pk":"515103","name":"唐澤山神社拝殿","kana":"からさわやまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市富士町字富士山1409-3他","lat":36.35374722,"lng":139.60073333,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造、銅板葺、建築面積42㎡","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0266","desc":"明治期別格官幣社の拝殿。本殿を囲む透塀の外に位置する。入母屋造銅板葺、二軒疎垂木で隅の軒反り優雅。吹寄格天井として、正背面中央間に板扉を立てる他は蔀戸で四方に開放的で縁を巡らす。組物は舟肘木で簡素ながら端正な造りで制限図式の影響を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014561"},{"id":"00014560","register_sub_id":"101","register_pk":"515102","name":"唐澤山神社本殿","kana":"からさわやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市富士町字富士山1409-3他","lat":36.35393889,"lng":139.60080278,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造、銅板葺、建築面積5.1㎡","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0265","desc":"史跡唐沢山城跡の本丸に所在する明治期別格官幣社の本殿。一間社流造銅板葺、二軒繁垂木、組物舟肘木とし、前方への屋根の流れが大きく緩やか。四方に切目縁と刎高欄を巡らし浜縁付。菊紋の金具等を除けば装飾は簡素だが、木柄太く制限図式の影響が明らか。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014560"},{"id":"00012291","register_sub_id":"101","register_pk":"531615","name":"旧東照宮宝物館","kana":"きゅうとうしょうぐうほうもつかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和後","pref":"栃木県","address":"栃木県日光市山内2281-3","lat":36.75634444,"lng":139.59800556,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"鉄筋コンクリート造2階建地下1階、銅板葺、建築面積958㎡","structure_material":"鉄筋コンクリート造2階建地下1階","registered":"2018.05.10(平成30.05.10)","register_no":"09-244","desc":"日光山内に建つ鉄筋コンクリート造のもと博物館で、設計は岸田日出刀による。一階を執務、二階を展示の空間にあて、周囲に高欄付テラスを廻し正面中央に大階段を設ける。板葺風の緩勾配屋根や壁外に出した梁など、伝統表現が特徴的なモダニズム建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012291"},{"id":"00015002","register_sub_id":"101","register_pk":"529280","name":"桜町二宮神社拝殿及び幣殿","kana":"さくらまちにのみやじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県真岡市物井字東峰高2013-2","lat":36.40796944,"lng":140.01546389,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"09 - 0277","desc":"本殿南の基壇上に建つ拝殿及び幣殿。拝殿は入母屋造銅板葺、正面に一間向拝と千鳥破風を付し、背面に切妻造銅板葺の幣殿を突出する。拝殿は三方に刎高欄付縁を廻らし脇障子を建てる。内部は一室の畳敷で格天井を張る。全体に質実なつくりとした拝殿及び幣殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015002"},{"id":"00015001","register_sub_id":"101","register_pk":"529279","name":"桜町二宮神社本殿","kana":"さくらまちにのみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県真岡市物井字東峰高2013-2","lat":36.40808611,"lng":140.0155,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.6㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"09 - 0276","desc":"二宮尊徳没後八十年を記念し、史跡桜町陣屋跡東方に建立した神社本殿。覆屋内の基壇上に南面して建つ一間社流造銅板葺で、三方に刎高欄付縁を廻らし脇障子を建て、正面に木階を付す。円柱に三斗を組み、妻飾は豕扠首とする。装飾を抑えた質実なつくりの本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015001"},{"id":"00004121","register_sub_id":"101","register_pk":"105111","name":"長林寺開山堂","kana":"ちょうりんじかいざんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町2884","lat":36.34234528,"lng":139.44426786,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積23㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0108","desc":"本堂の背後に建つ。方１５尺の北面に３尺の張出を設けた平面に銅板葺の宝形屋根を架ける。奥正面の張出部を開祖殿とし，屋根北面に天窓を開け，東西壁面上部に引き違い窓を設ける。本堂と同様に小林福太郎の設計による鉄筋コンクリート造の近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004121"},{"id":"00004120","register_sub_id":"101","register_pk":"105110","name":"長林寺本堂","kana":"ちょうりんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町2884","lat":36.34227317,"lng":139.44417997,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積153㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0107","desc":"鉄筋コンクリート造による寺院建築の好例。設計は小林福太郎。桁行５間梁間４間，寄棟造，青緑釉薬瓦の本瓦葺本堂で，外部側柱を胴張付き円柱，入側柱を六角柱とし，一軒繁垂木や出三斗組，内部の虹梁や天井化粧垂木の手挟等も鉄筋コンクリートで造り上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004120"},{"id":"00004522","register_sub_id":"101","register_pk":"105512","name":"東照宮武徳殿","kana":"とうしょうぐうぶとくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県日光市山内2301","lat":36.75613,"lng":139.600708,"geo_status":"db","era":"大正4／昭和6増改造","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積353㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"09 － 0120","desc":"徳川家康三百年大遠忌に際し，参拝人休憩所として建設。当初は桁行７間梁間４間，土間床の堂で，設計は大江新太郎。改修時に柱を根継して基壇を嵩上げし，四周に裳階を付すとともに内部は床を張り，内法長押を加える。日光における近代和風建築の一例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004522"},{"id":"00003058","register_sub_id":"101","register_pk":"104048","name":"日本キリスト教団佐野教会","kana":"にほんきりすときょうだんさのきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県佐野市金屋仲町2431","lat":36.31116441,"lng":139.57780669,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積129㎡、塔屋付","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"09 － 0063","desc":"佐野駅南方に位置する。木造二階建，切妻造とし，主体部と屋根勾配を揃えた塔屋を棟の前方に設ける。外装は下見板張で，正面にバラ窓風の丸窓と尖頭アーチの開口部を左右対称に配し，全体的にゴシック風の造りとしながらも，内部の柱に大斗風の桁受を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003058"},{"id":"00013044","register_sub_id":"101","register_pk":"368350","name":"乃木神社拝殿","kana":"のぎじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県那須塩原市石林字狩野道上793-2","lat":36.88755278,"lng":140.00278889,"geo_status":"db","era":"大正4年／昭和12年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0251","desc":"背面の本殿との間に幣殿を置き、南面して建つ。桁行五間、梁間三間、切妻造平入銅板葺で、柱間装置を設けない開放的なつくり。太い円柱を並べ長押を廻し、組物は置かない。千木や鞭掛のなどに神明造の細部を取入れた簡明な外観で、静謐な社頭景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013044"},{"id":"00013043","register_sub_id":"101","register_pk":"368349","name":"乃木神社本殿","kana":"のぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県那須塩原市石林字狩野道上793-2","lat":36.88767222,"lng":140.00293889,"geo_status":"db","era":"大正4年／昭和12年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0250","desc":"那須塩原市域南東にある乃木希典夫妻を祀る神社。本殿は敷地北奥に南面して建つ、切妻造妻入銅板葺で、直線的な構成で端正な外観をもつ社殿。住吉大社本殿に類似した形式とする一方で、千木の形式を神明造風とするなど、近代らしい自由な構成の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013043"},{"id":"00005249","register_sub_id":"101","register_pk":"106237","name":"一宮家住宅（般若坊）主屋","kana":"いちのみやけじゅうたく（はんにゃぼう）しゅおく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県高崎市榛名山町164","lat":36.45337149,"lng":138.84907355,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積650㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0153","desc":"榛名神社の社家町にあり，参道東側の敷地中央に東西棟の宿坊が位置し，南へ折れた南北棟に玄関と台所を配す。東側には２階建の居住部分が接続する。宿坊は棟通りの廊下の両側に８畳または６畳の客室を配し，縁を巡らす。屋根は切妻造，桟瓦葺である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005249"},{"id":"00005250","register_sub_id":"101","register_pk":"106238","name":"一宮家住宅（般若坊）長屋門","kana":"いちのみやけじゅうたく（はんにゃぼう）ながやもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県高崎市榛名山町164","lat":36.45342794,"lng":138.84893475,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0154","desc":"敷地南西隅，参道に西面する桁行６間，梁間２間の長屋門で，北半を門，南半を門番室とする。門番室の東面に桁行３間，梁間２間の土間を付ける。屋根は鉄板平葺で，外壁は真壁造，白漆喰塗で，腰は押縁下見板張とする。社家町の参道の景観を形成し貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005250"},{"id":"00005251","register_sub_id":"101","register_pk":"106239","name":"門倉家住宅（善徳坊）主屋","kana":"かどくらけじゅうたく（ぜんとくぼう）しゅおく","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県高崎市榛名山町176","lat":36.45377696,"lng":138.84957734,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、鉄板葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0155","desc":"榛名神社の社家町の住宅を兼ねる宿坊で，参道に西面して建つ間口６間半，奥行４間半の切妻造，鉄板瓦棒葺，平入で，東面南寄りに台所を後方に突き出す。正面中央に式台玄関を備え，南西隅に土間を設ける。小規模ながら同地区最古の宿坊遺構と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005251"},{"id":"00000524","register_sub_id":"101","register_pk":"101514","name":"旧日本基督教団沼田教会紀念会堂","kana":"きゅうにほんきりすときょうだんぬまたきょうかいきねんかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県沼田市都市計画事業沼田市中心市街地土地区画整理事業２－３街区１１５８－２、１１５９－１","lat":36.64495,"lng":139.04760278,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造２階建，スレート葺，建築面積112㎡","structure_material":"木造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"10 － 0026","desc":"生糸貿易で栄えた星野家の寄附によって建てられた会堂を美術館として再利用した建物。市内で数少ない大正期の洋風建築で，外壁の下見板，縦長の上下窓，急勾配の屋根等にその特徴がよくあらわれている。設計・施工は埼玉県和戸町出身の大工小菅幸之助。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000524"},{"id":"00001039","register_sub_id":"101","register_pk":"102029","name":"光恩寺石蔵","kana":"こうおんじいしぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県邑楽郡千代田町大字赤岩甲1041","lat":36.20824974,"lng":139.43982192,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"石造二階建，瓦葺，建築面積40㎡","structure_material":"石造二階建","registered":"1999.02.17(平成11.02.17)","register_no":"10 － 0038","desc":"客殿の東方に位置し，客殿の妻面に接して建つ。大谷石を用いた２階建，東西棟，平入の石蔵で，南面に半間程度の瓦葺の庇をさしかけて蔵前とし，２階南面にふたつの小庇付き窓を穿つ。庫裏・客殿とともに寺の奥向き部を構成する主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001039"},{"id":"00001038","register_sub_id":"101","register_pk":"102028","name":"光恩寺客殿","kana":"こうおんじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県邑楽郡千代田町大字赤岩甲1041","lat":36.20829089,"lng":139.43976157,"geo_status":"db","era":"明治時代後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治時代後期","structure":"木造平屋建，瓦葺，建築面積62㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"10 － 0037","desc":"長屋門を入って突き当たりに位置する。庫裏の北東端に接続する平屋建，瓦葺，切妻造，東西棟の建物で，山を背にし，南前面に庭園を造る。南面の庭園側に縁側を張り出した上質な造りの離れ座敷になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001038"},{"id":"00003813","register_sub_id":"101","register_pk":"104803","name":"正田醤油地内稲荷神社","kana":"しょうだしょうゆちないいなりじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県館林市栄町3-1","lat":36.24760569,"lng":139.52552634,"geo_status":"db","era":"江戸末期／平成14移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0111","desc":"八号蔵の南方に位置する。桁行３間梁間２間，東西棟，切妻造，妻入の本殿の前方に，桁行３間梁間２間，南北棟，切妻造，向拝付，平入の拝殿を配した社殿。醸造場敷地内に取込まれているが，地元地区の稲荷として現在も近隣住民から親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003813"},{"id":"00005253","register_sub_id":"101","register_pk":"106241","name":"鐸木家住宅（本坊）門","kana":"たくきけじゅうたく（ほんぼう）もん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県高崎市榛名山町183","lat":36.45387387,"lng":138.85022476,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、銅板葺、間口3.0m","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0157","desc":"榛名神社二之鳥居から東へ石段を登った高台の敷地西端に建つ。薬医門の形式で本柱の柱間１０尺，本柱と控え柱の間は７尺とする。控え柱の上に大斗と実肘木を組み，虹梁をあげて梁を受ける。屋根は切妻造で銅板葺である。南側に脇門が附属する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005253"},{"id":"00004331","register_sub_id":"101","register_pk":"105321","name":"日本基督教団安中教会温古亭（旧牧師館）","kana":"にほんきりすときょうだんあんなかきょうかいおんこてい（きゅうぼくしかん）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県安中市安中3-19-10","lat":36.32925479,"lng":138.89803942,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"10 － 0120","desc":"牧師館として建設。教会堂とは道を隔てた南側の敷地に東西棟で建つ。切妻造，桟瓦葺の木造平屋建で，もと安中藩家老屋敷の一部と伝える８畳と１０畳の座敷を核とし，東側に玄関と台所など，西側に４畳半の和室を配し，座敷南面には半間幅の縁を付す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004331"},{"id":"00004332","register_sub_id":"101","register_pk":"105322","name":"日本基督教団安中教会義圓亭（旧柏木義圓書斎）","kana":"にほんきりすときょうだんあんなかきょうかいぎえんてい（きゅうかしわぎぎえんしょさい）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県安中市安中3-19-10","lat":36.32933969,"lng":138.89788562,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"10 － 0121","desc":"温古亭の北西に位置。桁行２間梁間３間，切妻造，鉄板葺の木造平屋建で，６畳２室の西側に下屋を差し掛けて土間と便所に充て，南面東端に玄関を設ける。真壁造の簡素な建物であるが，たちが高いのが特徴で，開口部が多く，高窓もあり書斎に相応しいつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004332"},{"id":"00004330","register_sub_id":"101","register_pk":"105320","name":"日本基督教団安中教会教会堂（新島襄記念会堂）","kana":"にほんきりすときょうだんあんなかきょうかいきょうかいどう（にいじまじょうきねんかいどう）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県安中市安中3-10-33","lat":36.32959083,"lng":138.89766376,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造平屋一部2階建、銅板葺、建築面積171㎡、鐘塔付","structure_material":"石造平屋一部2階建","registered":"2004.11.08(平成16.11.08)","register_no":"10 － 0119","desc":"東を正面とした大谷石造のロマネスク会堂で，東南隅部に角形鐘塔を建て，外壁に控壁を付ける。内部は単廊であるが，天井は板張りで，中央をヴォールト状にして三廊式の扱いとし，アプス両脇にはコンポジット式の大理石円柱を建てる。設計は古橋柳太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004330"},{"id":"00004333","register_sub_id":"101","register_pk":"105323","name":"日本基督教団安中教会宣教師館（旧ベーケン邸）","kana":"にほんきりすときょうだんあんなかきょうかいせんきょうしかん（きゅうべーけんてい）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県安中市安中3-19-9","lat":36.329124,"lng":138.897827,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"10 － 0122","desc":"温古亭の西南方に位置する。切妻造，桟瓦葺の木造２階建で，外壁は１階イギリス下見板張，２階モルタル塗とする。南面にベイウィンドーを張出し，屋根に３本の煙突を立ち上げるなど明治大正期の外国人宣教師館を継承したつくりに特徴。教会付属施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004333"},{"id":"00015139","register_sub_id":"101","register_pk":"530563","name":"日本基督教団桐生教会教会堂","kana":"にほんきりすときょうだんきりゅうきょうかいきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市錦町一丁目994-1","lat":36.40679167,"lng":139.33439167,"geo_status":"db","era":"昭和5年／昭和31年増築、同44年・平成4年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積254㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"10 - 0352","desc":"ＪＲ桐生駅南方の市街地に北面して建つ切妻造妻入鉄板葺の教会堂。正面は三連の尖頭アーチの中央を玄関アルコーブとし、上部に三葉形アーチ窓を開けバルコニーを付す。会堂は単廊式で祭壇を尖塔アーチで飾る。上部に現したシザーズトラスが上昇感をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015139"},{"id":"00007002","register_sub_id":"101","register_pk":"107984","name":"日本基督教団島村教会教会堂","kana":"にほんきりすときょうだんしまむらきょうかいきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県伊勢崎市境島村2509-2","lat":36.245003,"lng":139.245697,"geo_status":"db","era":"明治30／昭和25増築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積86㎡","structure_material":"木造平屋一部2階建","registered":"2008.04.18(平成20.04.18)","register_no":"10 － 0257","desc":"田園風景の中に建つ木造の小教会堂。屋根は桟瓦葺で北の平屋部を切妻造、南の２階部を半切妻造とし、東面南寄りに切妻屋根の玄関が付く。外壁は下見板張で２階を漆喰塗とする。小屋組はキングポスト・トラス。玄関部の簡素なハーフチンバー風意匠が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007002"},{"id":"00006783","register_sub_id":"101","register_pk":"107765","name":"日本聖公会高崎聖オーガスチン教会聖堂","kana":"にほんせいこうかいたかさきせいおーがすちんきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県高崎市山田町8-1","lat":36.331966,"lng":139.007172,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、スレート葺、建築面積158㎡、鐘塔付","structure_material":"鉄筋コンクリート造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"10 － 0253","desc":"鉄筋コンクリート造平屋建の単廊式教会である。北側道路に面した西端に尖頭アーチの出入口を設ける。交叉部北の角塔形鐘楼は、四隅にバットレスを付ける。屋根はスレート瓦葺。小屋組は木造シザーズ・トラスとする。簡潔な意匠のネオ・ゴシック風教会堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006783"},{"id":"00002508","register_sub_id":"101","register_pk":"103498","name":"前橋カトリック教会聖堂","kana":"まえばしかとりっくきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県前橋市大手町2-14-6","lat":36.389671,"lng":139.065109,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋一部3階建、スレート葺、建築面積375㎡","structure_material":"鉄筋コンクリート造平屋一部3階建","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0085","desc":"県庁東南方に位置し東面して建つ。正面左右に下部四角，上部八角の塔を立上げた双塔形式の会堂で，内部は３廊式とする。身廊部天井を８分ヴォールトとするなどゴシック式を基調とするが，身廊部の簡明な壁面構成や陸屋根状の側廊部などモダンな取扱いも特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002508"},{"id":"00011451","register_sub_id":"101","register_pk":"210419","name":"歓喜院閼伽井堂","kana":"かんぎいんあかいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.227956,"lng":139.375102,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0162","desc":"仁王門の南に位置し、東面する。木造平屋建、入母屋造銅板葺で、平面は中央に井戸を据えた方三メートルの土間と水天宮を祀る一室よりなる。井戸廻りは木柵を建て込んで開放とする。虹梁や木鼻、支輪には精緻な彫刻を施し、小規模ながら上質の設えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011451"},{"id":"00011453","register_sub_id":"101","register_pk":"210381","name":"歓喜院五社大明神","kana":"かんぎいんごしゃだいみょうじん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.228261,"lng":139.374363,"geo_status":"db","era":"天明3年（1783）／平成23年改修","year":1783,"year_source":"db","year_min":1783,"year_max":1783,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0164","desc":"聖天堂背面三社の中央に建つ。桁行五間、梁間二間、切妻造銅板葺で、後方一間に五神を祀り、手前一間を見世棚とする。軸部は弁柄塗とする。軒廻り見世棚上部を虹梁で繋ぎ、妻は彩色を施した笈形付き二重虹梁大瓶束とするなど華やかである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011453"},{"id":"00011449","register_sub_id":"101","register_pk":"210418","name":"歓喜院籠堂","kana":"かんぎいんこもりどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.228301,"lng":139.375218,"geo_status":"db","era":"明治12年／昭和30年代後半増築","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造2階建、瓦葺、建築面積185㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0160","desc":"聖天堂の北東に位置する祈願者のための籠堂。木造二階建、寄棟造桟瓦葺で、南東に唐破風造銅板葺の玄関を付す。平面は一、二階とも八畳六室を二列に並べ、四周に廊下を廻らし、西面に大床を備える。二階には平書院、透彫欄間を備える。境内景観を構成する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011449"},{"id":"00011452","register_sub_id":"101","register_pk":"210380","name":"歓喜院三宝荒神社","kana":"かんぎいんさんぽうこうじんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.228382,"lng":139.374405,"geo_status":"db","era":"天明7年（1787）／平成23年改修","year":1787,"year_source":"db","year_min":1787,"year_max":1787,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.9㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0163","desc":"聖天堂背面三社のうち北寄りに建つ。一間社流造、素木造、銅板葺の小社で、庇は浜縁、浜床を設け、四周の高欄は繰型付の板持送りで支持する。軒廻りも独特な形の虹梁や海老虹梁、蟇股や支輪、庇柱木鼻などの彫刻で賑やかに飾り、高い大工技術を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011452"},{"id":"00011450","register_sub_id":"101","register_pk":"210402","name":"歓喜院鐘楼","kana":"かんぎいんしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.228332,"lng":139.375005,"geo_status":"db","era":"宝暦11年（1761）／大正期・昭和26年改修","year":1761,"year_source":"db","year_min":1761,"year_max":1761,"year_label":null,"structure":"木造2階建、瓦葺、建築面積35㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0161","desc":"籠堂の西に建つ。石造とコンクリート造の二重の基壇上に建つ入母屋造桟瓦葺の鐘楼。下層は柱間に横板壁を建て込んで四周を囲み、西面に上層への階段を設ける。上層は吹放ちで四周に縁を張出す。後の改造もあって建ちの高い特異な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011450"},{"id":"00011454","register_sub_id":"101","register_pk":"210420","name":"歓喜院天満社","kana":"かんぎいんてんまんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.22816,"lng":139.374339,"geo_status":"db","era":"天明5年（1785）／平成23年改修","year":1785,"year_source":"db","year_min":1785,"year_max":1785,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.8㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0165","desc":"聖天堂背面三社のうち南寄りに建つ。一間社流造、素木造、銅板葺の小社で、庇は浜縁、浜床に木階五級を設け、四周の高欄は繰型付の板持送で支持する。軒廻りの虹梁の形、各部の彫刻など、三宝荒神社とほぼ同じ形で、境内の形成過程を知ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011454"},{"id":"00011455","register_sub_id":"101","register_pk":"210421","name":"歓喜院仁王門","kana":"かんぎいんにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.22804,"lng":139.375249,"geo_status":"db","era":"明治27年","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0166","desc":"参道の奥、聖天堂の正面に建つ五間三戸の大規模な門で、左右に仁王像を安置する。屋根は入母屋造瓦棒銅板葺である。丸柱上の頭貫木鼻と台輪は隅、平ともに突出させ、出組組物で軒を支え、中備に蟇股を据える。中央間虹梁には花鳥の精緻な彫刻を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011455"},{"id":"00011457","register_sub_id":"101","register_pk":"210423","name":"歓喜院平和の塔","kana":"かんぎいんへいわのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"昭和中","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.228765,"lng":139.375086,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造多宝塔、銅板葺、建築面積17㎡","structure_material":"木造多宝塔","registered":"2017.05.02(平成29.05.02)","register_no":"11-0168","desc":"境内北方の小高い場所に建つ。戦没者の供養と世界恒久平和を祈願して建てられた。総欅造の木造多宝塔で、下層組物は出組とし軒は二軒繁垂木、上層は三手先、軒は二軒扇垂木とする。蟇股など細部に復古的な特徴が見られる、第二次大戦後の記念碑的多宝塔の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011457"},{"id":"00011456","register_sub_id":"101","register_pk":"210422","name":"歓喜院水屋","kana":"かんぎいんみずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.227945,"lng":139.375322,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、面積3.4㎡","structure_material":"木造","registered":"2017.05.02(平成29.05.02)","register_no":"11-0167","desc":"仁王門の正面南寄りに建つ。桁行一間梁間一間、切妻造桟瓦葺で、柱を内転びとし、中央に石製の水盤を据える。軒廻りは出組で太い虹梁を支え、虹梁、大ぶりの蟇股、支輪に様々な彫刻を施すなど規模に比して豪奢で重厚な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011456"},{"id":"00015290","register_sub_id":"101","register_pk":"532414","name":"越谷久伊豆神社神楽殿","kana":"こしがやひさいずじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県越谷市越ヶ谷1700","lat":35.90139444,"lng":139.79062778,"geo_status":"db","era":"明治前期／昭和中期改修、同49年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、銅板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"11 - 0233","desc":"境内の北東、参道の東に建つ神楽殿。正面は方一間の舞台で背面に楽屋を付した、入母屋造妻入銅板葺。舞台の三方に刎高欄付縁を廻らして脇障子を付し、舞台と楽屋境に板戸を建てる。正面寄りの軒は、吹寄の扇垂木とした丁寧なつくりで、参道沿いの景観を演出。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015290"},{"id":"00015291","register_sub_id":"101","register_pk":"532415","name":"越谷久伊豆神社手水舎","kana":"こしがやひさいずじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市越ヶ谷1700","lat":35.901275,"lng":139.79051944,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、銅板葺、面積4.4㎡、手水鉢付","structure_material":"木造","registered":"2025.03.13(令和7.03.13)","register_no":"11 - 0234","desc":"神楽殿の南、参道の東に建つ手水舎。方一間入母屋造瓦棒銅板葺で両妻面に軒唐破風を付す。柱を四方転びに立て、組物は出組、軒は二軒繁垂木。斜めに出す丸彫の龍鼻や籠彫の持送、虹梁形頭貫、中備など随所を彫刻で飾り軒唐破風と相まって華麗な外観の手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015291"},{"id":"00015289","register_sub_id":"101","register_pk":"532413","name":"越谷久伊豆神社本殿","kana":"こしがやひさいずじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市越ヶ谷1700","lat":35.90191667,"lng":139.79056111,"geo_status":"db","era":"寛政元年(1789)","year":1789,"year_source":"db","year_min":1789,"year_max":1789,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"11 - 0232","desc":"越谷の市街地中心部に鎮座する神社本殿。南面して建つ三間社流造瓦棒銅板葺で、三方に腰組付縁を廻らし脇障子を建てる。組物は出組、妻飾は二重虹梁大瓶束、軒は二軒繁垂木。庇柱、虹梁形頭貫、木鼻、中備などに精緻な素木の彫刻を付し、装飾華やかな本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015289"},{"id":"00013691","register_sub_id":"101","register_pk":"505207","name":"金剛寺山門","kana":"こんごうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県比企郡川島町大字中山字中廓1198","lat":35.98929167,"lng":139.451425,"geo_status":"db","era":"嘉永5年(1852)","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"11 － 203","desc":"境内南辺に南面して建つ切妻造桟瓦葺の四脚門。本柱は円柱で冠木で繋ぎ、控柱は角柱で腰貫、頭貫を通して軸部を固める。組物は出組で妻飾は二重虹梁大瓶束とし、軒は二軒繁垂木とする。隅行に獅子鼻を掛けて、冠木上を龍の彫刻で飾った丁寧な造りの山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013691"},{"id":"00013690","register_sub_id":"101","register_pk":"505205","name":"金剛寺大日堂","kana":"こんごうじだいにちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県比企郡川島町大字中山字中廓1198","lat":35.98978333,"lng":139.45191667,"geo_status":"db","era":"江戸中期／大正15年・昭和55年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"11 － 202","desc":"本堂東方に南面して建つ。正面一間側背面二間宝形造銅板葺。側廻りは角柱で切目長押、内法長押で緊結し、組物は舟肘木、軒は二軒繁垂木とする。内部は内外陣境に円柱を立て組物は出三斗とし、壁画や天井画を残す。外部の小壁を古式な蟇股や彫刻で飾る仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013690"},{"id":"00013229","register_sub_id":"101","register_pk":"366218","name":"世界無名戦士之墓","kana":"せかいむめいせんしのはか","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"埼玉県","address":"埼玉県入間郡越生町大字越生字岡崎935","lat":35.96422778,"lng":139.28939722,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積210㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2020.04.03(令和2.04.03)","register_no":"11 － 0195","desc":"大観山山頂に位置する鉄筋コンクリート造三階建で、東面して建つ。戦後に身元不明の遺骨等を祀った礼拝施設。四分の一円弧平面の納骨室を建上げ、正面にフルーティングを施し、中央に半円形の礼拝室を構える。地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013229"},{"id":"00002519","register_sub_id":"101","register_pk":"103509","name":"日本聖公会川越キリスト教会礼拝堂","kana":"にほんせいこうかいかわごえきりすときょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県川越市松江町2-4-13","lat":35.921143,"lng":139.485352,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造平屋建、スレート葺、建築面積138㎡、塔屋付","structure_material":"煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"11 － 0036","desc":"立教大学新築のため来日したＷ．ウィルソンの設計により建設。東西に細長い切妻造・平屋建で，外壁煉瓦造，内部は挟み組み式の小屋組を見せ，尖塔アーチの縦長窓や控壁にゴシック様式細部を備える。Ｔ字路の突き当たりに建ち，際だった景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002519"},{"id":"00004946","register_sub_id":"101","register_pk":"105936","name":"日本聖公会熊谷聖パウロ教会門","kana":"にほんせいこうかいくまがやせいぱうろきょうかいもん","category":"宗教","subcategory":"その他工作物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県熊谷市宮町1-139","lat":36.14678676,"lng":139.38383514,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造、間口4.5m","structure_material":"煉瓦造","registered":"2005.11.10(平成17.11.10)","register_no":"11 － 0090","desc":"鐘塔を兼ねた礼拝堂玄関ポーチに対応した位置に建つ。門の間口は内法で２．２ｍ，東側に脇門を設ける。門柱は煉瓦造で，煉瓦長手２枚角，脇門柱は１枚半角とする。門柱根積部との境に柾立ての層を挟み，礼拝堂と合わせた積み方とするのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004946"},{"id":"00004945","register_sub_id":"101","register_pk":"105935","name":"日本聖公会熊谷聖パウロ教会礼拝堂","kana":"にほんせいこうかいくまがやせいぱうろきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県熊谷市宮町1-139","lat":36.14670986,"lng":139.38374942,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積141㎡","structure_material":"煉瓦造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"11 － 0089","desc":"焼過煉瓦を効果的に用いた煉瓦造教会。桁行約１６ｍ，梁行約７ｍ規模の単廊式会堂で，東面北端に鐘塔を建ち上げ下部を玄関ポーチとし，外壁要所に尖頭アーチ窓とバットレスを配す。内部は煉瓦壁を顕わにし，木造シザーストラスを架ける。設計はＷ．ウィルソン。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004945"},{"id":"00014140","register_sub_id":"101","register_pk":"508770","name":"八條八幡神社本殿","kana":"はちじょうはちまんじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県八潮市大字八條字堤外4069","lat":35.85589722,"lng":139.83876389,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡、覆屋付","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"11-0218","desc":"中川西岸微高地に所在する旧八條村の鎮守で１間社流造社殿。２手先組物に腰組は４手先とし、向拝柱の龍を始め夥しい彫刻で飾る。圧巻は側面羽目板で大日本帝国憲法発布を題材とした彫刻を１枚板浮彫で飾る。時事を題材とした社殿の彫刻は希少で、趣が深い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014140"},{"id":"00006261","register_sub_id":"101","register_pk":"107245","name":"日野岡家住宅長屋門","kana":"ひのおかけじゅうたくながやもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県比企郡鳩山町大字須江407","lat":36.002007,"lng":139.32664339,"geo_status":"db","era":"江戸後期／昭和54・56・平成4改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積74㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"11 － 0107","desc":"丘陵の南裾にあり，南面して建つ。東西棟の寄棟造，もと茅葺で，平面は桁行１５．７ｍ，梁間４．６ｍの規模を有し，中央に門口を構え，両側を部屋とする。軒は出桁造，小屋は扠首組で，正面外壁の腰は押縁下見板張とする。形式は簡素であるが，丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006261"},{"id":"00016490","register_sub_id":"101","register_pk":"574852","name":"林泉寺表門（赤門）","kana":"りんせんじおもてもん（あかもん）","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"宝暦6年（1756）","year":1756,"year_source":"db","year_min":1756,"year_max":1756,"year_label":null,"structure":"木造、瓦葺、間口3.4m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0246","desc":"本堂の西方に西面して建つ一間一戸の四脚門。切妻造桟瓦葺で、主柱は五平柱とし、軸部は腰貫、内法貫、頭貫で固める。棟通りは扇に日の丸の浮彫をあしらった蟇股や、吹寄菱格子で飾るなど意匠上の見所とする。全体を朱塗とし、地域が赤門と呼び親しむ表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016490"},{"id":"00016487","register_sub_id":"101","register_pk":"574849","name":"林泉寺子安観音堂","kana":"りんせんじこやすかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"宝暦12年（1762）／昭和51年改修","year":1762,"year_source":"db","year_min":1762,"year_max":1762,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0243","desc":"本堂西方に南面して建つ子安観音堂。桁行3間梁間3間、入母屋造桟瓦葺で、銅板葺の1間向拝を切下げて付し、四周に縁を廻す。台輪上に三斗を組み、軒は二軒繁垂木。内部は一室の畳敷で棹縁天井を張り、背面側に仏壇を構える。全体に当初形式を良く残す小堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016487"},{"id":"00016489","register_sub_id":"101","register_pk":"574851","name":"林泉寺地蔵堂","kana":"りんせんじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"江戸後期／昭和51年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、建築面積7.5㎡","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0245","desc":"境内西方に南面して建つ地蔵堂。三間四方宝形造桟瓦葺で柱間は正面中央間を広くし、三方に縁を廻らす。軸部は角柱で桁を直接支え、軒は一軒繁垂木。内部は板敷の一室で棹縁天井を張り、背面側に通しの仏壇を構える。全体に質実なつくりで、寺観を整える小堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016489"},{"id":"00016488","register_sub_id":"101","register_pk":"574850","name":"林泉寺鐘楼堂","kana":"りんせんじしょうろうどう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"延享5年（1748）","year":1748,"year_source":"db","year_min":1748,"year_max":1748,"year_label":null,"structure":"木造、瓦葺、面積6.8㎡","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0244","desc":"本堂の南西に位置する鐘楼堂。切石積基壇に建つ方一間、入母屋造桟瓦葺で、面取角柱を四方転びに立て、腰貫・内法貫・頭貫で固め、台輪を廻す。組物は絵様肘木に三斗組を重ねた特徴的な形式で、中備は蟇股。軒は二軒繁垂木。落着いた外観で境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016488"},{"id":"00016486","register_sub_id":"101","register_pk":"574848","name":"林泉寺本堂","kana":"りんせんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"延宝元年（1673）頃／寛保2年(1742)頃・文政8年（1825）頃・昭和45年改修","year":1673,"year_source":"db","year_min":1673,"year_max":1673,"year_label":null,"structure":"木造、瓦葺、建築面積171㎡","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0242","desc":"市街地北東に位置する浄土宗寺院の本堂。境内東寄りに西面して建つ入母屋造桟瓦葺で、正面に一間向拝を付す。平面は前方を外陣、後方中央を内陣、両側を脇陣とし、内陣に禅宗様須弥壇を配し、格天井に草花の彩色画を華やかに飾る。境内景観の中核をなす本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016486"},{"id":"00016491","register_sub_id":"101","register_pk":"574853","name":"林泉寺脇門（黒門）","kana":"りんせんじわきもん（くろもん）","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.0m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0247","desc":"赤門の南方に西面して建つ一間一戸の薬医門。切妻造桟瓦葺で、主柱間、控柱間に桁を渡して梁を架け、梁上の束で棟木を受け、梁の前後で軒桁を受ける。軒は一軒疎垂木で、門口に板戸を吊る。小規模ながら境内南西の景観をつくり、地域が黒門と呼び親しむ脇門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016491"},{"id":"00016354","register_sub_id":"101","register_pk":"536421","name":"大日堂","kana":"だいにちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県笠間市箱田字長町2210他","lat":36.39923889,"lng":140.23468333,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"08 - 0322","desc":"市街地の北西に位置し、日本画家木村武山が建立した持仏堂。池に東面して建つ宝形造本瓦葺で頂部の路盤中央に宝珠、四隅に鳳凰を飾る。内部は一室の玉石敷で中央に据えた八角須弥壇に厨子を安置。壁の仏画や天井の花鳥図など、武山が絵筆を揮った渾身の仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016354"},{"id":"00015400","register_sub_id":"101","register_pk":"533415","name":"日本聖公会土浦聖バルナバ教会礼拝堂","kana":"にっぽんせいこうかいつちうらせいばるなばきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県土浦市中央一丁目6-イ-1","lat":36.08443611,"lng":140.19705,"geo_status":"db","era":"昭和5年／平成13年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺一部銅板葺、建築面積175㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"08 - 0321","desc":"土浦城跡の西に位置する教会の礼拝堂。平屋建切妻造桟瓦葺の東西棟で、礼拝堂の西に玄関と鐘楼、東に集会室を附属する。鉄筋コンクリート造の壁式構造で、内部は木造トラスの小屋組を現す。四角平面に八角屋根を載せた鐘楼を外観のアクセントとする礼拝堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015400"},{"id":"00003950","register_sub_id":"101","register_pk":"104940","name":"密弘寺不動堂","kana":"みっこうじふどうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁184","lat":36.277584,"lng":140.098633,"geo_status":"db","era":"天保11","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"08 － 0123","desc":"名水不動の名で地元に親しまれる真言宗寺院の小堂。方３間，宝形造，桟瓦葺で，正面に向拝を設け，内部は１室で奥に須弥壇，左右脇壇を造り付ける。丸柱上に出組を組み，軒は二軒繁垂木，頭貫木鼻，向拝回りに篭彫，丸彫の派手な彫刻を付し整った姿をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003950"},{"id":"00001492","register_sub_id":"101","register_pk":"102482","name":"香雲閣","kana":"かうんかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県香取市香取1697-1","lat":35.88733452,"lng":140.52951259,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積304㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"12 － 0036","desc":"香取神宮社殿の北東に南面して建ち，集会や直会に用いられてきた２階建，寄棟造の和風建築で，一部の造作を除き，明治３３年頃に完成した。１階正面に唐破風造の玄関を設けて大規模ながら均整の取れた外観とし，境内空間に調和した構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001492"},{"id":"00002134","register_sub_id":"101","register_pk":"103124","name":"香取神宮拝殿・幣殿・神饌所","kana":"かとりじんぐうはいでん・へいでん・しんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県香取市香取1697-1","lat":35.88609531,"lng":140.52871628,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積298㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"12 － 0038","desc":"内務省神社局による昭和１１年からの大修築により建設。重文の本殿（元禄１３年）正面に権現造風に幣殿・拝殿を繋げ，拝殿正面に千鳥破風と軒唐破風を付ける。軸部を黒漆塗，組物・蟇股を極彩色とするなど本殿の意匠と釣り合った体裁をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002134"},{"id":"00016493","register_sub_id":"101","register_pk":"574855","name":"旧茂木佐平治家住宅金宝殿手水舎","kana":"きゅうもぎさへいじけじゅうたくきんぽうでんちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東中町350-4","lat":35.937995,"lng":139.86641778,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、面積3.4㎡","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"12 - 0339","desc":"本社の参道北に建つ手水舎。本瓦葺の切妻屋根は照り起りの唐破風形とする。四隅の柱は内転びで龍彫刻を飾る。頭貫は亀甲紋の地紋彫、獅子鼻とし、斗栱間に亀、唐破風懸魚に狐と宝珠の彫刻を飾る。彫刻濃密な近代和風建築で、天井に掲げた雷神の高浮彫が圧巻。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016493"},{"id":"00016492","register_sub_id":"101","register_pk":"574854","name":"旧茂木佐平治家住宅金宝殿本社","kana":"きゅうもぎさへいじけじゅうたくきんぽうでんほんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東中町350-4","lat":35.937995,"lng":139.86641778,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡、宮殿付","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"12 - 0338","desc":"茂木佐公園に隣接する旧醤油醸造家の屋敷社。東面して建つ入母屋造妻入本瓦葺で向唐破風向拝付、四周に縁を廻らす。内陣正面は格子戸引分、外陣は畳敷とする。向拝柱は亀甲形の六角柱で龍彫刻を施し、木鼻、蟇股、羽目板など内外を彫刻で濃密に飾った本社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016492"},{"id":"00001247","register_sub_id":"101","register_pk":"102237","name":"九十九里教会","kana":"くじゅうくりきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県山武市松尾町松尾60-1","lat":35.63986121,"lng":140.45620376,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積100㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"12 － 0028","desc":"木造、瓦葺切妻屋根、下見板貼の素朴なキリスト教会堂建築であるが、軒回りを塗込め、正面に入母屋屋根の玄関ポーチを付けるなど後の時代の木造ゴシックの教会堂とは趣を異にする点に特徴がある。ヘボンゆかりの教会として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001247"},{"id":"00001491","register_sub_id":"101","register_pk":"102481","name":"選擇寺本堂","kana":"せんちゃくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県木更津市中央1-5-6","lat":35.384075,"lng":139.923111,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積232㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"12 － 0035","desc":"木更津市街にある昭和５年に建てられた寺院本堂。鉄筋コンクリート造であるが，向拝付の木造３間仏堂の形態を採用し，組物や軒廻り等の細部を忠実に再現している。伝統的様式を踏襲しながら，耐久性を目指した寺院建築として，時代の特徴をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001491"},{"id":"00008649","register_sub_id":"101","register_pk":"149370","name":"大巌寺書院","kana":"だいがんじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県千葉市中央区大巌寺町180-1","lat":35.57427987,"lng":140.14610393,"geo_status":"db","era":"江戸末期／昭和30年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積372㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"12 － 0152","desc":"本堂の東に南面して建つ。切妻造鉄板葺で、千鳥破風状に窓を設け、正面に中央に入母屋造妻入の玄関を付設する。建築面積372㎡。東半部は2列各3室を並べ、北に畳縁を通し、西寄りに南北に3室を配し、4周に縁を通す。教学の場の雰囲気を残す書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008649"},{"id":"00008648","register_sub_id":"101","register_pk":"149369","name":"大巌寺本堂","kana":"だいがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県千葉市中央区大巌寺町180-1","lat":35.57412996,"lng":140.14590881,"geo_status":"db","era":"江戸中期／明治36年・昭和23年・昭和後期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積476㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"12 － 0151","desc":"境内の北奥に南面して建つ。桁行5間梁間4間、寄棟造桟瓦葺を主体部とし、その周囲に下屋をまわし、正面に唐破風造桟瓦葺の向拝を付設する。主体部は外陣と内陣、脇の間等からなり、内陣には須弥壇を構える。18世紀中葉に遡る数少ない浄土宗檀林遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008648"},{"id":"00001173","register_sub_id":"101","register_pk":"102163","name":"長興院山門","kana":"ちょうこういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県成田市伊能556","lat":35.83786963,"lng":140.43199424,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造楼門，瓦葺，建築面積22㎡","structure_material":"木造楼門","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0015","desc":"総欅造り，楼門形式の門。彫刻をあまり用いないなど簡素な意匠になるが，組物を詰組にするなど細部には工夫もみられる。上層部のせいが高く，内部に十六羅漢を祀る（現在は本堂内に保管）点に，よく時代の特徴があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001173"},{"id":"00007341","register_sub_id":"101","register_pk":"108323","name":"日本福音ルーテル市川教会会堂","kana":"にほんふくいんるーてるいちかわきょうかいかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県市川市市川4-288-14","lat":35.738251,"lng":139.9058721,"geo_status":"db","era":"昭和30／平成5改修","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建塔屋付、鉄板葺、建築面積148㎡","structure_material":"木造2階建塔屋付","registered":"2008.10.23(平成20.10.23)","register_no":"12 － 0114","desc":"梁間７．３ｍ桁行１７ｍの木造教会堂で、南北棟の切妻造瓦型鉄板葺屋根をもつ単廊式の礼拝堂と、その東面南寄りに建つ４階建の鐘楼からなる。平滑な白色の外壁に、正面や鐘楼上部に丸窓、身廊側面に半円アーチ窓を開ける。ヴォーリズ晩年の作品のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007341"},{"id":"00001168","register_sub_id":"101","register_pk":"102158","name":"茂原昇天教会","kana":"もばらしょうてんきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県茂原市茂原581","lat":35.42448804,"lng":140.29724583,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積113㎡","structure_material":"木造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0010","desc":"木造平屋建、下見板貼、単廊式の礼拝堂で、平面の輪郭はラテン十字形を描く。ハーフティンバー風に仕上げられた身廊部正面の切妻と、正方形と八角形断面のカップルとなったトスカナ式の柱によって支持された玄関ポーチとが端正なファサードを造っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001168"},{"id":"00016495","register_sub_id":"101","register_pk":"574857","name":"よろこび寮表門","kana":"よろこびりょうおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東中町350-4","lat":35.937995,"lng":139.86641778,"geo_status":"db","era":"大正15年頃／昭和中期改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造、鉄板葺、間口2.1m、脇塀付","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"12 - 0341","desc":"会堂の東正面、茂木佐公園との境に建つ腕木門。冠木上の板欄間は中央を透かせて門灯を設け、背面は腕木下を控柱で受ける。門口は板扉を両開に吊り、左右に斜めに延ばした袖塀は、竪板張で上部の欄間に丸竹を渡し、笠木を載せる。全体に繊細なつくりの表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016495"},{"id":"00016494","register_sub_id":"101","register_pk":"574856","name":"よろこび寮会堂","kana":"よろこびりょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県野田市野田350","lat":35.94549778,"lng":139.86378583,"geo_status":"db","era":"大正15年／平成17年頃改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"12 - 0340","desc":"茂木佐公園の西に位置する仏教修養団体の会堂。平屋建寄棟造桟瓦葺で全体矩折の平面。東面北寄りに玄関を設け、南に八畳二室の座敷、西側の突出部に居室と水回りを配す。座敷は床柱に檳榔樹、床框や落掛に黒檀など、床廻りに銘木を用いた瀟洒なつくりの会堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016494"},{"id":"00001374","register_sub_id":"101","register_pk":"102364","name":"阿豆佐和気命神社旧本殿","kana":"あづさわけのみことじんじゃきゅうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都利島村1","lat":34.52967219,"lng":139.27699138,"geo_status":"db","era":"文久4","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造平屋建、板葺、建築面積3.1㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"13 － 0063","desc":"利島は伊豆諸島の大島と新島の間にあり，当社は「延喜式神名帳」にも小社として記されている。棟札より離島における数少ない江戸時代末期の神社本殿建築。簡素であるが本式の細部様式を備えており，類例の少ない２間社流造として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001374"},{"id":"00010927","register_sub_id":"101","register_pk":"208898","name":"御嶽神社社務所","kana":"おんたけじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都大田区北嶺町145-1他","lat":35.586091,"lng":139.681071,"geo_status":"db","era":"昭和5／昭和26改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積154㎡","structure_material":"木造平屋一部2階建","registered":"2016.02.25(平成28.02.25)","register_no":"13-0360","desc":"境内西方に東面して建つ。南北棟の社務所で、中央に起りのある切妻破風と入母屋屋根を架ける玄関を突き出す。玄関の間の南には一五畳の応接室を設け、東側に座敷飾を設ける。床に南洋材などの銘木を用い、折上格天井を張って格式を高める良質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010927"},{"id":"00010926","register_sub_id":"101","register_pk":"208897","name":"御嶽神社水行堂","kana":"おんたけじんじゃすいぎょうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都大田区北嶺町145-1他","lat":35.586177,"lng":139.68115,"geo_status":"db","era":"慶応3（1867）頃","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積18㎡、井戸付","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"13-0359","desc":"境内西方に東面して建つ。東西棟、切妻造妻入で、三間四方の内部を前後二室に区切る。水垢離をするための施設で、井戸を有する。正面の両脇間に花頭窓を開け、頭貫を虹梁として、上部に龍の彫刻欄間を嵌めて飾る。木鼻の形状などに時代的特徴が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010926"},{"id":"00010925","register_sub_id":"101","register_pk":"208896","name":"御嶽神社末社一山神社祖霊社","kana":"おんたけじんじゃまっしゃいっさんじんじゃそれいしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都大田区北嶺町145-1他","lat":35.586321,"lng":139.681145,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"13-0358","desc":"御嶽神社を創建した一山行者を祀り、境内西方に南面して建つ。東西棟の拝殿から丁字に本殿を突出し、正面に一間向拝を設ける。本殿は後方に祭壇を造り付け、手前を畳敷の幣殿とする。拝殿は折上格天井とし、洋風灯具を吊る。簡明な意匠を持つ近代小規模社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010925"},{"id":"00013693","register_sub_id":"101","register_pk":"504967","name":"海福寺本堂","kana":"かいふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都目黒区下目黒三丁目679-2","lat":35.62934722,"lng":139.70931111,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積215㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"13 － 449","desc":"黄檗宗寺院本堂。入母屋造桟瓦葺で東面する。桁行一三・八メートル、梁間九・八メートルで正面北寄りに向拝を付け、背後に寄棟造の突出部を張出す。北列は正面から広縁、室中、内陣とし奥に須弥壇を設ける。南列は二室の客間。区内で貴重な戦前建立の仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013693"},{"id":"00002615","register_sub_id":"101","register_pk":"103605","name":"カトリック神田教会聖堂","kana":"かとりっくかんだきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区西神田1-1-12","lat":35.699387,"lng":139.757355,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋一部2階建、瓦葺、建築面積643㎡","structure_material":"鉄骨鉄筋コンクリート造平屋一部2階建","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0120","desc":"水道橋南方に位置し街路の角地に立つ。バシリカ形式の三廊式聖堂で，半円アーチを基調とした開口部，ロンバルド帯風の軒蛇腹，四葉をモチーフとした胴蛇腹が外観を飾り，半円アーチのヴォールト天井と玄関脇に集会所を設ける平面を特徴とする。設計ヒンデル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002615"},{"id":"00013968","register_sub_id":"101","register_pk":"508228","name":"寛永寺葵の間","kana":"かんえいじあおいのま","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都台東区上野桜木一丁目10","lat":35.72156944,"lng":139.77468889,"geo_status":"db","era":"江戸末期／大正3年・平成25年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0453","desc":"根本中堂の東に所在する書院造の建築。主座敷一〇畳の北が次の間八畳で、西に一間幅の広縁がつく。主座敷は床の南に下地窓、床脇は地袋棚である。次の間は壁と天井を紙張、北に一畳大の板敷がつく。東に雪隠が接続する。数寄屋風を加味した上質な座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013968"},{"id":"00002369","register_sub_id":"101","register_pk":"103359","name":"寛永寺護国院庫裏","kana":"かんえいじごこくいんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区上野公園10-18","lat":35.71925,"lng":139.769821,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋一部2階建、2階部を除く、瓦葺、建築面積386㎡","structure_material":"木造平屋一部2階建","registered":"2001.10.12(平成13.10.12)","register_no":"13 － 0111","desc":"護国院本堂の西方に建ち，客殿部と住居部から成る。客殿部は，７間×２間規模の中庭を有し，北側に玄関・応接室・役僧室等を，南側に１２畳半の客間と１０畳２室を東西に並べ，四周に縁廊下を廻す。岡田信一郎が手がけた数少ない和風建築のひとつとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002369"},{"id":"00013967","register_sub_id":"101","register_pk":"508227","name":"寛永寺根本中堂","kana":"かんえいじこんぽんちゅうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都台東区上野桜木一丁目10","lat":35.721425,"lng":139.77439167,"geo_status":"db","era":"明治12年／昭和60年改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積368㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0452","desc":"境内南西に西面して建つ桁行七間、梁間七間の大型仏堂である。入母屋造本瓦葺で、尾垂木付の二手先組物が二軒繁垂木の軒を受ける。内部は後方の三間が内陣で、宮殿廻りはもと土間であった。天井全体を鏡天井とする。根本中堂の形式の本格的な天台宗寺院本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013967"},{"id":"00003521","register_sub_id":"101","register_pk":"104511","name":"神田神社神饌所","kana":"かんだじんじゃしんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70198194,"lng":139.76815963,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、銅板葺、建築面積19㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0152","desc":"本殿東方に位置し，桁行・梁間各２間，入母屋造，２軒繁垂木，本瓦型銅板葺で，東面に張出しを付す。内部は拭板敷で，南東隅に踏込土間を設ける。小規模ながら高い基壇上に建ち，主要社殿同様全体を弁柄色塗とし，随所に金箔押金具を飾り格式と荘厳を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003521"},{"id":"00003525","register_sub_id":"101","register_pk":"104515","name":"神田神社西門","kana":"かんだじんじゃにしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70210451,"lng":139.7677372,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造、銅板葺、間口1.8m、玉垣折曲り延長14m付","structure_material":"鉄骨鉄筋コンクリート造","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0156","desc":"宝庫南方に脇障子風板塀を介して接続する。外側は基壇上に載り，北より第２間に門口を開き，両開桟唐戸を吊り込む。北方に１間，南方には拝殿側面まで矩ね折れ５間に北半と同形式の玉垣を回す。拝殿及び宝庫とともに，複合社殿正側面の構成上欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003525"},{"id":"00003520","register_sub_id":"101","register_pk":"104510","name":"神田神社拝殿","kana":"かんだじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70191154,"lng":139.76783966,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、銅板葺、建築面積335㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0151","desc":"中央間を広く取った桁行７間，梁間６間，入母屋造，本瓦型銅板葺で，正面５間に向拝を付し，両脇突出部に切妻屋根を架ける。内部は前方四半敷の土間，後方畳敷床上部とする。社殿群中最大の建物で，伝統的構成を基本にしつつ，装飾や比例に新感覚が充溢する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003520"},{"id":"00003524","register_sub_id":"101","register_pk":"104514","name":"神田神社東門","kana":"かんだじんじゃひがしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70188986,"lng":139.76803507,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造、銅板葺、間口1.8m、玉垣折曲り延長14m付","structure_material":"鉄骨鉄筋コンクリート造","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0155","desc":"神饌所南方に脇障子風板塀を介して接続する。外側は基壇上に載り北より第２間に門口を開き両開桟唐戸を吊り込む。北方に１間，南方には拝殿側面まで矩ね折れに５間，北半と同形式の玉垣を回す。拝殿，神饌所とともに，複合社殿正側面の構成上欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003524"},{"id":"00003519","register_sub_id":"101","register_pk":"104509","name":"神田神社幣殿","kana":"かんだじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70201454,"lng":139.76790848,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、銅板葺、建築面積46㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0150","desc":"本殿と拝殿を繋ぐ。間口３３尺，桁行１５尺，両下造，本瓦型銅板葺。内部は拝殿と同高に畳敷の床を張り，台輪上の組物で，中央折上げ，両脇組入天井を受ける。本殿側軸部は金箔押で組物に繧繝彩色を施す。伝統的手法を基本に，随所に新規の納まりが見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003519"},{"id":"00003522","register_sub_id":"101","register_pk":"104512","name":"神田神社宝庫","kana":"かんだじんじゃほうこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.702179,"lng":139.76779079,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、銅板葺、建築面積17㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0153","desc":"本殿西方神饌所とほぼ対称の位置に建つ。高床の校倉形式になり，台輪上に大斗舟肘木を載せ，２軒繁垂木の軒を受け，屋根は入母屋造，本瓦型銅板葺とする。伝統的形式を基本としながら，校倉の最下部を肘木で受ける納まりなど，要所に特徴ある新造形を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003522"},{"id":"00003518","register_sub_id":"101","register_pk":"104508","name":"神田神社本殿","kana":"かんだじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70211098,"lng":139.76799629,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、銅板葺、建築面積63㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0149","desc":"鉄骨鉄筋コンクリート造，入母屋造平入，本瓦型銅板葺で，梁間前方２間を外陣，奥１間を内陣とし，軒は出組，２軒繁垂木とする。伊東忠太が顧問，大江新太郎，佐藤功一が設計の震災復興社殿群の中心建物で，伝統的な木造の繊細な比例，意匠を巧みに踏襲する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003518"},{"id":"00003523","register_sub_id":"101","register_pk":"104513","name":"神田神社瑞垣","kana":"かんだじんじゃみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70220129,"lng":139.76807525,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄骨鉄筋コンクリート造、銅板葺、延長60m","structure_material":"鉄骨鉄筋コンクリート造","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0154","desc":"本殿周囲を神饌所と宝庫の間で折れ回りに囲う透塀。柱を地，腰，内法の各長押で固め，腕木で出桁を受け，疎垂木，本瓦型銅板葺屋根を載せる。北面中央に門を開き，その他の柱間は上半を連子窓，腰部は吹寄せに襷桟を打つ。社殿群北半の構えに欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003523"},{"id":"00013969","register_sub_id":"101","register_pk":"508229","name":"観音寺客殿","kana":"かんのんじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都台東区谷中五丁目107-1","lat":35.72550833,"lng":139.76810833,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積232㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0454","desc":"境内中央の本堂南に並ぶ寄棟造南北棟で、東に切妻屋根に霧除庇を廻した玄関を突出、内玄関は唐破風庇がつく。南側が庫裏で、北側の玄関奥に続き間の客殿を配す。主座敷15畳は、西に畳床、天袋付違い棚を設け、付書院を備える。端正な意匠の寺院殿舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013969"},{"id":"00001561","register_sub_id":"101","register_pk":"102551","name":"観音寺築地塀","kana":"かんのんじついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都台東区谷中5-8-28","lat":35.7253012,"lng":139.76806339,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"練塀、瓦葺、延長37.6m","structure_material":"練塀","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0076","desc":"観音寺は明和９年（１７７２）の火災で灰燼に帰した後，文政年間頃に再興された。築地塀は境内の南面を画する延長３７．６ｍのいわゆる練り塀で，瓦と粘土を交互に積み重ねて造り，潜り戸一所を備える。浅草と並ぶ江戸有数の寺町であった当時の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001561"},{"id":"00008262","register_sub_id":"101","register_pk":"133904","name":"教證寺客殿","kana":"きょうしょうじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都台東区池之端1-104他","lat":35.70934006,"lng":139.76896805,"geo_status":"db","era":"明治36年／大正15年改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"13 － 0261","desc":"敷地の北東隅に、南側で本堂に接続して建つ。桁行１４ｍ梁間５．５ｍの木造２階建、東西棟の入母屋造桟瓦葺。外壁は下見板張で、妻飾は木連格子とする。東面に大きく開いた廊下を座敷に面して付し、不忍池への眺望を意識していたことが立面に表れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008262"},{"id":"00008261","register_sub_id":"101","register_pk":"133903","name":"教證寺本堂","kana":"きょうしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都台東区池之端1-104他","lat":35.70923775,"lng":139.76893236,"geo_status":"db","era":"安政4年(1857)／大正15年改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積169㎡","structure_material":"土蔵造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"13 － 0260","desc":"敷地中ほどに西面して建つ。桁行９．９ｍ梁間１５ｍの土蔵造、寄棟造妻入桟瓦葺で、正面向拝一間、側背面を葺き降ろす。内部は外陣と内陣、余間等から構成される浄土真宗平面になる。向拝や軒まわりまでを塗り込めた土蔵造仏堂の代表的遺構のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008261"},{"id":"00005107","register_sub_id":"101","register_pk":"106097","name":"キリスト友会フレンズセンター","kana":"きりすとゆうかいふれんずせんたー","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都港区三田4-8-19","lat":35.642616,"lng":139.738281,"geo_status":"db","era":"大正11／昭和5増築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、スレート葺、建築面積142㎡、地下室付","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"13 － 0190","desc":"宣教師館として建設。木造２階建一部地下室付き，屋根は寄棟造スレート葺，外壁はモルタル塗で，玄関庇，縦長の上げ下げ窓，大きな屋根窓，煉瓦煙突等が外観を特徴付ける。ヴォーリズ建築事務所の設計で，数少ない関東大震災前の西洋館の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005107"},{"id":"00010123","register_sub_id":"101","register_pk":"197956","name":"功運寺庫裏","kana":"こううんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都中野区上高田4-14-19","lat":35.712367,"lng":139.678361,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"13 － 0344","desc":"境内の中央西寄りに南面して建つ木造平屋建で、入母屋造桟瓦葺である。南の玄関から取次ぎ七畳を経て中廊下を南北に通し、東に座敷一一畳と仏間八畳が並び、北に数寄屋風で七畳の方丈を配す。座敷から方丈にかけて縁を廻らす。丁寧な造作の近代和風建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010123"},{"id":"00010125","register_sub_id":"101","register_pk":"197958","name":"功運寺山門","kana":"こううんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都中野区上高田4-14-3","lat":35.711905,"lng":139.678414,"geo_status":"db","era":"大正3／平成22改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、間口3.2m、左右袖塀付","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"13 － 0346","desc":"境内南の参道に開く一間高麗門で、切妻造本瓦葺とし、控柱上と左右各二間の袖塀は桟瓦葺とする。本柱は角柱で棟木までのばし、冠木上の女梁と男梁で桁を受ける。軒は二軒繁垂木で、門扉と袖塀は竪格子とする。ケヤキの良材を多用し、施工も上質な山門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010125"},{"id":"00010124","register_sub_id":"101","register_pk":"197957","name":"功運寺鐘楼","kana":"こううんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都中野区上高田4-14-3","lat":35.712134,"lng":139.67838,"geo_status":"db","era":"寛延2頃／大正3移築","year":1749,"year_source":"db","year_min":1749,"year_max":1749,"year_label":null,"structure":"木造、瓦葺、面積6.0㎡","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"13 － 0345","desc":"高い石積基壇上に建つ方一間の鐘楼で、入母屋造本瓦葺である。内転びの粽付円柱を、腰貫、虹梁、頭貫で固め、格天井を張る。台輪上に出組を詰組に配し、軒は二軒繁垂木とする。籠彫の頭貫木鼻、獅子形の虹梁木鼻、虹梁上の蟇股など、要所を豊かな彫刻で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010124"},{"id":"00007459","register_sub_id":"101","register_pk":"108441","name":"高岩寺本堂","kana":"こうがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都豊島区巣鴨3-51-2","lat":35.73580912,"lng":139.73551071,"geo_status":"db","era":"昭和32／昭和60改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造平屋地下1階建、瓦葺、建築面積267㎡","structure_material":"鉄筋コンクリート造平屋地下1階建","registered":"2009.01.08(平成21.01.08)","register_no":"13 － 0237","desc":"通りに南面する敷地の北西に建つ。桁行、梁間とも１５ｍ規模のＲＣ造。入母屋造本瓦葺で、背面に入母屋造屋根を突出し、正面に一間向拝を付け、地下に事務機能を集約する。伝統的な和様を基調としつつ、細部意匠等を単純化する造形的な試みがなされ、質も高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007459"},{"id":"00000952","register_sub_id":"101","register_pk":"132573","name":"廣度院表門及び練塀","kana":"こうどいんおもてもんおよびねりべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都港区芝公園1-8-16","lat":35.65724825,"lng":139.75104854,"geo_status":"db","era":"19世紀初期","year":1805,"year_source":"estimated","year_min":1801,"year_max":1810,"year_label":"19世紀初期","structure":"木造一間一戸薬医門，瓦葺，柱間2.8m，高さ4.6m，練塀左右総延長41.6m附属","structure_material":"木造一間一戸薬医門","registered":"1998.12.11(平成10.12.11)","register_no":"13 － 0043","desc":"増上寺境内の子院の一間一戸の薬医門と塀である。練塀は底部に間知石を置き，芯柱を用いずに土と瓦を交互に積み上げて壁体とする構造で，現在では用いられることがない。数多くの子院が集まって形成していた特異な都市景観を知るよすがとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000952"},{"id":"00010269","register_sub_id":"101","register_pk":"199042","name":"金剛院庫裏","kana":"こんごういんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都豊島区長崎1-28","lat":35.72717,"lng":139.695751,"geo_status":"db","era":"昭和9年／平成25年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積304㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"13-0349","desc":"本堂南東側に渡り廊下を介して建つ。東西棟で六間取形式の庫裏と、座敷三室を直列させた客殿を矩の手に接続した平面を持つ。庫裏西正面に入母屋造の玄関を構え、客殿屋根に千鳥破風を飾る。屋根をゆるく起らせ、客殿主室に洗練された造作の座敷飾を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010269"},{"id":"00010268","register_sub_id":"101","register_pk":"199041","name":"金剛院本堂","kana":"こんごういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都豊島区長崎1-28","lat":35.72728,"lng":139.695563,"geo_status":"db","era":"昭和29年／平成25年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、瓦葺、建築面積112㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"13-0348","desc":"方三間で宝形造の内陣の前面に、入母屋造で向拝付の外陣を構える。内陣は二重屋根頂部に相輪を戴き、軸部は円柱や皿斗付組物、高欄、軒支輪などを表す。外陣向拝には蟇股を飾る。古典建築の造形を単純化しつつ引用してまとめた鉄筋コンクリート造の寺院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010268"},{"id":"00015156","register_sub_id":"101","register_pk":"530580","name":"西徳寺本堂","kana":"さいとくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区竜泉一丁目74-1","lat":35.72340278,"lng":139.790375,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積445㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"13 - 0514","desc":"国際通り沿いに位置する浄土真宗寺院の本堂。設計は島田藤。基壇上に東面して建つ、鉄筋コンクリート造入母屋造本瓦葺で正面の大階段上に３間向拝を付す。軒は二軒繁垂木、持送りで出桁を受け軒天井を張る。軒廻りや縁高欄など斬新な外観意匠の震災復興本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015156"},{"id":"00003202","register_sub_id":"101","register_pk":"104192","name":"実相寺本堂","kana":"じっそうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区池上2-10-17","lat":35.580021,"lng":139.702911,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、金属葺、建築面積187㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0146","desc":"大正末に浅草より移転。正面６間，側面６間，入母屋造平入，正面向拝付で，側廻柱上に舟肘木を置く。内部は奥中央を内陣，両脇を位牌所とし，内陣前に外陣，両脇客殿を配し，正面及び両側面に畳縁を回す。平面や細部意匠に近代の日蓮宗寺院本堂の展開を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003202"},{"id":"00003203","register_sub_id":"101","register_pk":"104193","name":"実相寺門","kana":"じっそうじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都大田区池上2-10-17","lat":35.579906,"lng":139.702728,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、金属葺、間口3.6m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0147","desc":"本堂の前方に通りに南面して建つ。大型の薬医門で軒は二軒半繁垂木とする。柱上組物肘木、男梁、女梁の先端に派手な繰型を付け、冠木上に特徴ある異形の虹梁を架ける。欅材による上質な造りであるとともに、池上本門寺門前に広がる寺町景観に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003203"},{"id":"00014142","register_sub_id":"101","register_pk":"508772","name":"常行院納骨堂","kana":"じょうぎょういんのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都港区芝公園二丁目11-1","lat":35.65657222,"lng":139.75080833,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積33㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"13-0460","desc":"増上寺の東に位置する寺院の納骨堂。鉄筋コンクリート造、入母屋造桟瓦葺妻入、主体部は太い円柱に長押を廻して花頭窓を設け、唐破風の向拝は角柱で虹梁や蟇股で飾る。内部は一室で地下に納骨棚を備える。重厚な意匠の近代仏堂で、山内寺院の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014142"},{"id":"00011894","register_sub_id":"101","register_pk":"211138","name":"上宮寺鐘楼","kana":"じょうぐうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都渋谷区広尾五丁目2-2","lat":35.650486,"lng":139.719945,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、面積6.2㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"13-391","desc":"境内の北西隅に南北棟で建つ。方一間、吹放ち形式で、切妻造とする。切石積基壇上に建ち、礎石と礎盤の上に几帳面取の角柱を四方転びで立てる。台輪を置き、三斗で軒を支え、妻面は虹梁上に蟇股で棟木を支える。細部意匠が良質で境内の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011894"},{"id":"00011892","register_sub_id":"101","register_pk":"211136","name":"上宮寺本堂","kana":"じょうぐうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都渋谷区広尾五丁目2-2","lat":35.650522,"lng":139.720162,"geo_status":"db","era":"大正3年／平成17年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積254㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"13-389","desc":"広尾駅西方にあり西面する真宗寺院本堂。入母屋造妻入で、起り屋根の向拝を突出させる。妻飾の二重虹梁大瓶束や兎毛通しの彫刻で正面を飾る。広い外陣をもち余間左脇に稚子之間を設け、背面に座敷飾りを備えた二室を突出し細長い境内に応じた平面を採る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011892"},{"id":"00011893","register_sub_id":"101","register_pk":"211137","name":"上宮寺本堂応接部","kana":"じょうぐうじほんどうおうせつぶ","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都渋谷区広尾五丁目2-2","lat":35.650421,"lng":139.720165,"geo_status":"db","era":"大正3年頃／平成17年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"13-390","desc":"本堂の南に廊下を挟んで南北棟で接続する。入母屋造の玄関を張り出し、前室を介して三室を矩折れに配し、内庭に面する東側に畳廊下を付ける。長押を廻らすが、座敷飾りは設けず、簡明な意匠とする。玄関には櫛形欄間を設け落ち着いた表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011893"},{"id":"00002522","register_sub_id":"101","register_pk":"103512","name":"常照院本堂内陣","kana":"じょうしょういんほんどうないじん","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都港区芝公園1-8-9","lat":35.657635,"lng":139.752014,"geo_status":"db","era":"明和6","year":1769,"year_source":"db","year_min":1769,"year_max":1769,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積25㎡","structure_material":"土蔵造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"13 － 0115","desc":"常照院は芝増上寺の子院のひとつ。内陣はもと念仏堂で，戦災を免れ，後に外陣などを加えて本堂の体裁を整えた。方２間半の土蔵造で，正面には重厚な観音扉を設ける。内部は後方に構えた仏壇・厨子，黒漆塗の格天井など，華やかで濃密な空間をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002522"},{"id":"00002525","register_sub_id":"101","register_pk":"103515","name":"心光院表門","kana":"しんこういんおもてもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都港区東麻布1-1-5","lat":35.65802985,"lng":139.74438216,"geo_status":"db","era":"寛保3／昭和25移築","year":1743,"year_source":"db","year_min":1743,"year_max":1743,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2001.11.20(平成13.11.20)","register_no":"13 － 0118","desc":"心光院は増上寺別院のひとつ。昭和２５年，戦災を免れた表門とともに現在地に移った。１間１戸四脚門で，屋根本瓦葺，柱はすべて同高になる。軒廻りを２軒吹寄垂木とし，桁行の頭貫を成の高い虹梁型とした特徴があり，別院の門の造形の一端を現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002525"},{"id":"00011480","register_sub_id":"101","register_pk":"210446","name":"心光院本堂","kana":"しんこういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区東麻布一丁目1-1","lat":35.65815806,"lng":139.74447306,"geo_status":"db","era":"昭和30年","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"13-0374","desc":"第二次大戦の空襲で本堂を焼失し、昭和二五年に区画整理で現在地に移転後再建されたもの。木造平屋建、入母屋造桟瓦葺で、柱はヒノキで内陣及び須弥壇後方のみ円柱とする。全体を伝統的な手法でまとめるが、西面の格子ガラス窓などに近代的な要素も併せ持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011480"},{"id":"00004216","register_sub_id":"101","register_pk":"105206","name":"田無神社参集殿","kana":"たなしじんじゃさんしゅうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都西東京市田無町3-7-4","lat":35.72954772,"lng":139.54383543,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"13 － 0179","desc":"二ノ鳥居の西に，参道を介して社務所と向かい合って建つ。玄関は式台構とし，取次の間の北側に座敷が東西に三室並ぶ。床の間を神殿に見立てた上座敷の意匠，透彫の欄間，磨き丸太の縁桁等を特徴とする近代和風建築。設計は内務省関連の建築家と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004216"},{"id":"00003195","register_sub_id":"101","register_pk":"104185","name":"椿山荘三重塔","kana":"ちんざんそうさんじゅうのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都文京区関口2-10-8","lat":35.71251945,"lng":139.72460582,"geo_status":"db","era":"室町末期／大正14移築","year":1556,"year_source":"estimated","year_min":1540,"year_max":1573,"year_label":"室町末期","structure":"木造三重塔、銅板葺、建築面積29㎡","structure_material":"木造三重塔","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0139","desc":"広島県竹林寺に創建され大正１４年に藤田男爵邸（現椿山荘）に移築。和様を基調に各部に禅宗様を加味し，組物は三手先，軒は各層とも本繁平行垂木。移築時に軸部が改造されたが，外観は細部に至るまで本格的な構成をよくとどめ，苑内の景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003195"},{"id":"00015417","register_sub_id":"101","register_pk":"533432","name":"東京カテドラル鐘塔","kana":"とうきょうかてどらるしょうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都文京区関口三丁目19-1","lat":35.71429722,"lng":139.72605833,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造、高さ62m、建築面積12㎡","structure_material":"鉄筋コンクリート造","registered":"2025.08.06(令和7.08.06)","register_no":"13 - 0526","desc":"大聖堂の南に聳える鉄筋コンクリート造、高さ62メートルの鐘塔。平面は変形の菱形で立面は上部を逓減させた鋭い形状。頂部は矩形に刳抜いて４つの鐘を吊り、上部に立てる突芯先端は十字架を象る。大聖堂脇に並び建ち、丹下健三の独創性が発揮された鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015417"},{"id":"00015416","register_sub_id":"101","register_pk":"533431","name":"東京カテドラル聖マリア大聖堂","kana":"とうきょうかてどらるせいまりあだいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都文京区関口三丁目19-1","lat":35.71426944,"lng":139.72658056,"geo_status":"db","era":"昭和39年／平成19年改修","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積2，554㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2025.08.06(令和7.08.06)","register_no":"13 - 0525","desc":"目白台に位置する教会の大聖堂。８枚のＨＰシェルを立てかけた外観とし、各壁の境界となるガラス面が天頂部の十字架状トップライトへ繋がる。大理石床と膨らみあるコンクリート打放の壁で構成した内部へ天頂部から柔らかな光が注ぐ。丹下健三の代表作の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015416"},{"id":"00002220","register_sub_id":"101","register_pk":"103210","name":"日本基督教団根津教会","kana":"にほんきりすときょうだんねづきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区根津1-19-6","lat":35.719143,"lng":139.762894,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦一部金属板葺、建築面積185㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"13 － 0104","desc":"根津神社の門前町の一画に位置する。木造平屋建，切妻造，下見板張の教会堂で，北西隅に玄関，北東隅に聖壇を置く非対称の平面構成に特徴があり，尖頭アーチの窓を開けた切妻の妻面と玄関部のトンガリ屋根を載せた角塔が地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002220"},{"id":"00002221","register_sub_id":"101","register_pk":"103211","name":"日本基督教団根津教会門及び塀","kana":"にほんきりすときょうだんねづきょうかいもんおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区根津1-19-6","lat":35.71923437,"lng":139.76288307,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"煉瓦造、間口3.6m、塀延長7.8m","structure_material":"煉瓦造","registered":"2001.08.28(平成13.08.28)","register_no":"13 － 0105","desc":"敷地の北辺を区切る煉瓦造の門と塀。会堂側の塀は会堂妻面が道路から見えるように低く造り，玄関側には，礼拝堂玄関用と談話室玄関用の門として３基の門柱を建てる点に特徴がある。会堂の白と煉瓦の赤がコントラストをなし，地域のシンボルともなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002221"},{"id":"00003531","register_sub_id":"101","register_pk":"104521","name":"日本基督教団富士見丘教会","kana":"にほんきりすときょうだんふじみがおかきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区代沢2-32-2","lat":35.65920128,"lng":139.67025628,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積262㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0162","desc":"木造，２階建で，切妻造，東西棟の主体部南西に塔屋を付属する。礼拝堂は中央を広く取って身廊と側廊とに分け，東奥に聖壇を構える。全体に質素平明な意匠だが，外部の薔薇窓風レリーフや塔屋頂部のバトルメント，内部のハンマービームトラスなど要所を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003531"},{"id":"00000953","register_sub_id":"101","register_pk":"101943","name":"日本基督教団本郷中央教会","kana":"にほんきりすときょうだんほんごうちゅうおうきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区本郷3-37-9","lat":35.70733133,"lng":139.76238566,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造３階建塔屋付，建築面積517㎡","structure_material":"鉄筋コンクリート造３階建塔屋付","registered":"1998.12.11(平成10.12.11)","register_no":"13 － 0044","desc":"「中央会堂」（明治２３年，伊藤為吉設計）として親しまれた建物の震災復興建築。春日通りに面し，階下を幼稚園，階上を礼拝堂に充てたゴシック様式による会堂で，東北隅に重厚な角塔を建ち上げる。設計は川崎忍，原案はヴォーゲルとされる。施工は辻組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000953"},{"id":"00013966","register_sub_id":"101","register_pk":"508226","name":"日本基督教団弓町本郷教会","kana":"にほんきりすときょうだんゆみちょうほんごうきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区本郷二丁目132-1","lat":35.70678056,"lng":139.75744444,"geo_status":"db","era":"大正15年／昭和28年・同44年・同61年、平成25年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリートブロック造4階建、建築面積321㎡、塔屋付","structure_material":"鉄筋コンクリートブロック造4階建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0451","desc":"文京区市街地に建つ教会。外部は茶色の化粧ブロックで、半円アーチ窓を並べる。屋根は陸屋根で通り角地に塔屋を配す。設計者中村鎮が開発した中村式鉄筋コンクリートブロック構造による四階建の建築で、当時数多く開発された特殊ブロック造建築の優品の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013966"},{"id":"00007191","register_sub_id":"101","register_pk":"108173","name":"日本聖公会浅草聖ヨハネ教会","kana":"にほんせいこうかいあさくさせいよはねきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区蔵前2-22-2他","lat":35.70364,"lng":139.792252,"geo_status":"db","era":"昭和4／昭和30改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積271㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2008.07.08(平成20.07.08)","register_no":"13 － 0232","desc":"隅田川右岸の街区に位置する。西を正面とし、間口９．１ｍ奥行２２ｍのＲＣ造２階建の礼拝堂を北に、ＲＣ造３階建の談話室を南に設け、その間を階段室で繋ぐ。礼拝堂にはバットレスを付け、尖頭アーチ窓を開ける。ゴシック風意匠になるＲＣ造教会の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007191"},{"id":"00015297","register_sub_id":"101","register_pk":"532421","name":"日本聖公会東京教区東京聖十字教会聖堂","kana":"にほんせいこうかいとうきょうきょうくせいじゅうじきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都世田谷区若林四丁目220-5","lat":35.644875,"lng":139.65669167,"geo_status":"db","era":"昭和36年／平成14年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"13 - 0518","desc":"世田谷線松陰神社前駅に程近い閑静な住宅街に位置する聖堂。設計はレーモンド建築設計事務所。角柱状の集成材を内側に曲げてヴォールト形とした無柱の空間に、正面及び腰屋根に設けた窓のカラー膜から柔らかい光が注ぐ。祈りの場に相応しい静謐な空間を創出。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015297"},{"id":"00004126","register_sub_id":"101","register_pk":"105116","name":"日本聖公会東京教区東京諸聖徒教会礼拝堂","kana":"にほんせいこうかいとうきょうきょうくとうきょうしょせいときょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区千石2-18-4","lat":35.72389335,"lng":139.73908207,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階建、金属板葺、建築面積264㎡、鐘楼付","structure_material":"鉄筋コンクリート造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"13 － 0175","desc":"関東大震災後，現在地への移転に伴い建設されたもの。設計は米国人建築家バーガミニ，施工は清水組。第二次世界大戦時に屋根部分を焼失しているが，戦後復興された。コンクリートの量感のある外観が特徴的で，尖塔と共に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004126"},{"id":"00008824","register_sub_id":"101","register_pk":"162267","name":"日本バプテストキリスト教目白ヶ丘教会礼拝堂","kana":"にほんばぷてすときりすときょうめじろがおかきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都新宿区下落合2-416-3他","lat":35.71916051,"lng":139.70410665,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積299㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"13 － 0283","desc":"住宅地の角地に建つ礼拝堂。南北棟の切妻造で、鉄筋コンクリート造平屋建、建築面積299㎡に及ぶ。両側面に縦長窓を連続させ、東面北端には尖塔アーチ型の鐘楼を建てる。内部は大きな桁行のアーチで分割して独特の空間を造り、静謐な場とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008824"},{"id":"00009592","register_sub_id":"101","register_pk":"194588","name":"旗岡八幡神社絵馬殿","kana":"はたがおかはちまんじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都品川区旗の台3-852-1","lat":35.60452176,"lng":139.70834262,"geo_status":"db","era":"昭和3頃／昭和20頃・昭和37頃移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"13 － 0296","desc":"旗の台の高台にある境内南東隅に建つ。桁行三間梁間二間、入母屋造銅板葺で、下部を吹放し、小壁を竪板張とする。江戸時代には武士の崇敬を集め、近代に至るまで多くの絵馬が奉納された。木柄は細いが伸びやかで開放的。区内では戦災を免れた貴重な神社建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009592"},{"id":"00002524","register_sub_id":"101","register_pk":"103514","name":"妙定院上土蔵","kana":"みょうじょういんかみどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都港区芝公園4-9-8","lat":35.65396012,"lng":139.74683978,"geo_status":"db","era":"文化8","year":1811,"year_source":"db","year_min":1811,"year_max":1811,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"13 － 0117","desc":"妙定院境内の東辺にあり，熊野堂の北側に建ち，近世後期の境内構成をよく伝えている。切妻造，桟瓦葺，妻入の２階建土蔵で，北面に観音扉を開き，戸前の庇を設ける。棟札より熊野堂より遅れて實譽宝観の時の上棟と判り，現在も収蔵庫として用いられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002524"},{"id":"00002523","register_sub_id":"101","register_pk":"103513","name":"妙定院熊野堂","kana":"みょうじょういんくまのどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都港区芝公園4-9-8","lat":35.65389289,"lng":139.74683122,"geo_status":"db","era":"寛政8","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"13 － 0116","desc":"妙定院は芝増上寺の子院のひとつで，旧山内の南辺，赤羽川沿いにある。熊野堂は棟札より二世・進譽仰願が起立主と判明する。寄棟造，妻入の土蔵造で，内部は前１間半を外陣，奥１間を内陣として仏壇を設ける。近世後期に広まった土蔵造小堂の良好な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002523"},{"id":"00002758","register_sub_id":"101","register_pk":"103748","name":"妙福寺祖師堂（旧七面大明神堂）","kana":"みょうふくじそしどう（きゅうしちめんだいみょうじんどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都大田区南千束2-2-7","lat":35.60129783,"lng":139.69162467,"geo_status":"db","era":"天保4","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"13 － 0130","desc":"もと天保４年再建の七面大明神堂で，後に曳屋されて祖師堂となった。前側を外陣，奥に内陣・内々陣を延ばした平面を持つ奥行の深い三間堂で，桟瓦葺の屋根は正面入母屋造，背面寄棟造になる。規模は小さいが，洗足池畔の景観のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002758"},{"id":"00009717","register_sub_id":"101","register_pk":"195546","name":"祐天寺表門","kana":"ゆうてんじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.637245,"lng":139.69646227,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.6m、左右潜戸付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0302","desc":"駒沢通りに面する境内北辺に建ち、仁王門の前面に位置する。高麗門、切妻造桟瓦葺で、建ちが高く、冠木と棟木の間に竪格子をはめる。左右には潜戸をつけ、雄大な構えをもつ。境内の表門として、都内に残る有力寺院に見合った格式ある構えを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009717"},{"id":"00009715","register_sub_id":"101","register_pk":"195544","name":"祐天寺地蔵堂","kana":"ゆうてんじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.63729569,"lng":139.69677422,"geo_status":"db","era":"天明8／寛政12増築","year":1788,"year_source":"db","year_min":1788,"year_max":1788,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0300","desc":"正面三間側面五間で、正面寄棟造、背面入母屋造、向拝付とする。内部は内外陣に分けられ、背面一間をさらに虹梁等で区切って須弥壇を設け、厨子を安置する。内陣を折上格天井、外陣を江戸町火消の各組の纏を描いた格天井とし、内外陣境に欄間を嵌めて飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009715"},{"id":"00009716","register_sub_id":"101","register_pk":"195545","name":"祐天寺地蔵堂門","kana":"ゆうてんじじぞうどうもん","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.6372243,"lng":139.69661241,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.3m、左右袖塀付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0301","desc":"地蔵堂の前方に西面して建つ薬医門で、左右袖塀付。組物等の絵様刳形は時代相応のもので、妻飾では虹梁上の邪鬼で化粧棟木を受ける。天井の鏡板に火消組の纏七種を陽刻する独創的な意匠で、地蔵堂が江戸町火消の信仰と密接に結びついていたことを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009716"},{"id":"00009714","register_sub_id":"101","register_pk":"195543","name":"祐天寺書院","kana":"ゆうてんじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.63633914,"lng":139.69672901,"geo_status":"db","era":"明治28／平成21改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積329㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0299","desc":"本堂西方に北面する東西棟の寄棟造で、正面中央に玄関を構える。西寄りを板間とし、東側には前後二列に三室ずつ配る。南側の庭に面して主たる三室を並べ、東端室には大振りのトコと違棚を構え、風格ある座敷をなしている。都内では数少ない大規模書院の遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009714"},{"id":"00012304","register_sub_id":"101","register_pk":"531628","name":"祐天寺鐘楼","kana":"ゆうてんじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都目黒区中目黒五丁目1067-1","lat":35.63681667,"lng":139.69648056,"geo_status":"db","era":"享保14年(1729)／昭和7年改修","year":1729,"year_source":"db","year_min":1729,"year_max":1729,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"13-410","desc":"本堂北西方に位置する。桁行を広めた方一間吹放ち形式で、軒を一軒繁垂木とし、東西棟で切妻造、本瓦形銅板葺の屋根をかける。組物は三斗組、中備は木鼻付平三斗であり、妻面に虹梁をかけ笈形付大瓶束で飾る。細部絵様に江戸中期の意匠を示す鐘楼である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012304"},{"id":"00009713","register_sub_id":"101","register_pk":"195542","name":"祐天寺本堂","kana":"ゆうてんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.6365057,"lng":139.69700741,"geo_status":"db","era":"万延元／明治27移築・明治31・明治45増築・昭和35・平成21改修","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積379㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0298","desc":"万延元年に宝形造の内々陣、明治三一年に入母屋造の外陣、同四五年にそれらを繋ぐ内陣を設けて複合する。内々陣の室内は出組に折上格天井とし、幕末に活躍した絵師による草花図等で飾る。内陣と外陣は一体的な大空間となって、格調ある室内空間を実現する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009713"},{"id":"00009718","register_sub_id":"101","register_pk":"195547","name":"祐天寺水屋","kana":"ゆうてんじみずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.63685786,"lng":139.69670283,"geo_status":"db","era":"弘化3","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造、銅板葺、面積3.0㎡","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0303","desc":"本堂と仁王門の間に南北棟で建つ。方一間、入母屋造銅板葺で、角柱を内転びに立て、四方を吹き放つ。頭貫を虹梁様とし、隅と中備に三斗を置いて丸桁を受け、ケヤキの板支輪で折上天井を支える。天井中央に龍の丸彫を飾るなど、要所の彫刻も目を引く秀作である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009718"},{"id":"00014773","register_sub_id":"101","register_pk":"519031","name":"大山寺本堂","kana":"おおやまでらほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県伊勢原市大山字宝珠山727","lat":35.42930278,"lng":139.23936944,"geo_status":"db","era":"明治18年／昭和42年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積248㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0341","desc":"大山の中腹に東面して建つ真言宗寺院本堂。桁行五間梁間五間、入母屋造瓦型銅板葺。前二間を外陣、後三間を内陣と脇陣に画す密教系本堂で、太い柱が林立し雄大。正面の軒唐破風付向拝は木鼻の龍を始め彫刻が横溢し圧巻。大山詣の隆盛を伝える大型の近代仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014773"},{"id":"00002623","register_sub_id":"101","register_pk":"103613","name":"正眼寺庫裏","kana":"しょうげんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本562","lat":35.22855388,"lng":139.10029684,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、亜鉛鉄板葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"14 － 0067","desc":"東西に長い敷地の西側に位置する。銅板瓦棒葺，入母屋造，平入とし，前面に縁を廻し，真壁造とする。本堂に繋がる渡廊下が，内部の廊下と接続し，ほぼ中廊下式の平面を構成する。北東隅の八畳間に付書院を設ける。本堂と並列し，境内の景観に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002623"},{"id":"00010943","register_sub_id":"101","register_pk":"208914","name":"清浄光寺石垣及び築地塀","kana":"しょうじょうこうじいしがきおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.34696389,"lng":139.48723611,"geo_status":"db","era":"江戸末期／大正15頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石垣 石造、総延長53m 築地塀 土塀、瓦葺、総延長22m","structure_material":"石垣 石造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0216","desc":"境内南入口に建つ総門の東西に矩折れにのびて、門前の広場を区画する。安山岩切石を高さ一・九メートルに精緻に布積し、上端に延石を廻らせる。築地塀は惣門の東西方向のみ残る。熨斗瓦を丁寧に配し、屋根に桟瓦を葺く。近世以来の門前の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010943"},{"id":"00010939","register_sub_id":"101","register_pk":"208910","name":"清浄光寺宇賀神社","kana":"しょうじょうこうじうがじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.349198,"lng":139.488459,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、銅板葺、建築面積3.6㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0212","desc":"境内北奥に鎮座する。正面一間側面二間の前面に向拝を付け、全体に入母屋造妻入、軒唐破風付の屋根をかける。正背面の妻破風を火灯枠風とし、水引虹梁に籠彫持送を付し、上面に蓑束を立てて菖蒲桁を受けるなど特異性を示す。向拝廻りを彫刻で濃密に飾る境内社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010939"},{"id":"00010938","register_sub_id":"101","register_pk":"208909","name":"清浄光寺回向堂","kana":"しょうじょうこうじえこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.348834,"lng":139.488646,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0211","desc":"本堂北西方の高台に建つ、方一間裳階付の堂。屋根は宝形造銅板葺で、内部は床張の一室として身舎に折上小組格天井を張る。細部は和様基調で組物は身舎出組、裳階三斗とし、仏壇上に中世風意匠の蟇股を飾る。丁寧なつくりの堂で、境内に静謐さを醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010938"},{"id":"00010936","register_sub_id":"101","register_pk":"208907","name":"清浄光寺小書院","kana":"しょうじょうこうじこじょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.349088,"lng":139.487642,"geo_status":"db","era":"明治前期／昭和前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、銅板葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0209","desc":"御番方後方の山裾に渡廊下を介して建ち、遊行上人の公式法務や賓客接待に使用される。東西棟の寄棟造銅板葺で、内部は南北二列に三室ずつ並べ、両列とも西奥室に床を構えて周囲に縁を廻らし、対面所風の平面を持つ。開放的で、細部造作に気品を備えた書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010936"},{"id":"00010935","register_sub_id":"101","register_pk":"208906","name":"清浄光寺御番方","kana":"しょうじょうこうじごばんかた","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.348771,"lng":139.487759,"geo_status":"db","era":"大正2／昭和前期改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積226㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0208","desc":"境内北西を占める住居部の正面中央に建つ。入母屋造銅板葺で、正面の軒唐破風付の大振りな入母屋玄関は精緻な彫刻で飾り、遊行上人の出立などに用いる。内部は六間取方丈形式で、上間奥室に床などの座敷飾りを備える。寺格に相応しい品格を備えた接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010935"},{"id":"00010940","register_sub_id":"101","register_pk":"208911","name":"清浄光寺鐘楼","kana":"しょうじょうこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.348318,"lng":139.488216,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、銅板葺、面積11㎡","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0213","desc":"本堂南西の苑路沿いの石積基壇上に東西棟で建つ。方一間、吹放し形式の鐘楼で、切妻造銅板葺である。八角の四本柱を内転びに立てて貫三段で固め、三斗を組み、両妻の絵様虹梁上の大瓶束で棟木を受ける。内部は格天井を張る。境内中枢部の景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010940"},{"id":"00010942","register_sub_id":"101","register_pk":"208913","name":"清浄光寺惣門","kana":"しょうじょうこうじそうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.34695833,"lng":139.48740556,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、銅板葺、間口5.0m","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0215","desc":"境内の南端入口に建つ大型の冠木門。本柱は見付〇・七メートルの面取角柱を間口五メートルに立て、上端を頭巾金物で覆う。控柱との間を貫で固め、小屋根を架けて高麗門風とする。高さ七・二メートルを測る黒色の正門で、塀と共に古刹の門前に風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010942"},{"id":"00010941","register_sub_id":"101","register_pk":"208912","name":"清浄光寺手水舎","kana":"しょうじょうこうじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.347958,"lng":139.488464,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、面積13㎡","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0214","desc":"本堂前方に南北棟で建つ。方一間吹放し形式で、切妻造桟瓦葺。几帳面取角柱を内転びに立て、頭貫と台輪を廻らし、出組を詰組とする。妻飾りは二重虹梁大瓶束に流水の笈形を飾る。頭貫木鼻を籠彫とし、中備を鳥獣等の彫物とするなど、精緻な彫刻で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010941"},{"id":"00010937","register_sub_id":"101","register_pk":"208908","name":"清浄光寺百間廊下","kana":"しょうじょうこうじひゃっけんろうか","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.34878528,"lng":139.48835727,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0210","desc":"本堂と御番方を繋ぐ長い廊下で、境内の起伏により勾配や段差をもち、屈曲してのびる。梁間一間の切妻造桟瓦葺で、漆喰塗外壁に長押を廻らし、火灯窓を並べる。要所に御廟所や宇賀神社の礼拝所を備え、宗教施設としての性格も備えており、境内景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010937"},{"id":"00010934","register_sub_id":"101","register_pk":"208905","name":"清浄光寺本堂","kana":"しょうじょうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.348438,"lng":139.488671,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積841㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0207","desc":"境内奥寄りに南面する、入母屋造で桁行梁間とも三〇メートル規模の大堂。内陣の三面に広い外陣と脇陣を配する時宗本堂の特徴を示し、各陣とも高く格天井を張り広壮な内部を創る。正面の向拝や内部小壁の彫刻も秀逸で、総本山寺院らしい荘厳と華麗さを備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010934"},{"id":"00014577","register_sub_id":"101","register_pk":"515119","name":"總持寺仮真殿","kana":"そうじじかりしんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見二丁目2119","lat":35.50633889,"lng":139.66918333,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"14 - 0326","desc":"能登から鶴見への本山移転に際し真牌を祀った開山堂で現在は位牌堂。入母屋造平入桟瓦葺、正面側に切妻造相の間を設け、擬宝珠高欄付階段とその両側の廊下で信徒位牌堂と繋がる独特な構成。内部は一室で格天井と位牌壇を備え、背面で納骨堂の常照殿と繋がる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014577"},{"id":"00004713","register_sub_id":"101","register_pk":"105703","name":"總持寺香積台","kana":"そうじじこうしゃくだい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50641859,"lng":139.67150828,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積814㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0094","desc":"伽藍中心部の南東に位置し，禅宗寺院のいわゆる庫裏に相当する。西面して建つ大規模な２階建で，１階は事務室，２階は大広間とする。瓦葺，切妻造，妻入で，正面には切妻造の玄関を備え，妻壁に虹梁・蟇股・窓を巧みに配し，豪放な外観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004713"},{"id":"00004718","register_sub_id":"101","register_pk":"105708","name":"總持寺虎嘯窟","kana":"そうじじこしょうくつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.506763,"lng":139.669312,"geo_status":"db","era":"安政年間／明治44移築","year":1856,"year_source":"estimated","year_min":1854,"year_max":1859,"year_label":"安政年間","structure":"木造平屋建、瓦葺、建築面積137㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0099","desc":"仏殿の西方に南面して建つ貫首の居住施設。寄棟造，桟瓦葺，吹放しの庇を架ける。内部は１５畳と１７．５畳の座敷を東西に並べ，東・南・西の３方を畳敷広縁とする。各室とも床・棚を備え，蟻壁を廻し，彫刻欄間や彩色板戸を用いるなど，丁寧な書院造になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004718"},{"id":"00014578","register_sub_id":"101","register_pk":"515120","name":"總持寺虎嘯窟渡廊下","kana":"そうじじこしょうくつわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見二丁目1878-3","lat":35.50664444,"lng":139.66918889,"geo_status":"db","era":"明治44年頃","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"14 - 0327","desc":"放光堂と虎嘯窟を矩折に繋ぐ渡廊下。切妻造桟瓦葺、組物舟肘木、真壁造格子窓腰板張とする。虎嘯窟側に玄関を屋根葺下ろしで設け、放光堂寄り二間を二重虹梁蟇股として屋根を切上げ、床組み太鼓橋状にして床下を通路とする。貫首が使用した造りの良い渡廊下。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014578"}];
